/**
 * Wissensbasis der Plattform-Hilfe: kurze, konkrete Antworten je Bereich – sofort verfügbar, ohne KI-Aufruf.
 * Wird im Chat-Build direkt genutzt und im echten Betrieb als Grundlage/Ersatz, wenn kein Sprachmodell antwortet.
 */
export type HelpTopic = { id: string; title: string; keys: RegExp; answer: string };

export const HELP_TOPICS: HelpTopic[] = [
  // Genaue Einträge zuerst: Bei gleich vielen Treffern gewinnt der frühere – so verdrängt ein allgemeiner Eintrag keinen genauen.
  { id: "passwort-aendern", title: "Passwort ändern", keys: /passwort.*([äa]nder|aender|wechsel|neu)|([äa]nder|aender|wechsel|neues).*passwort|kennwort/i, answer: "Passwort ändern: Einstellungen → „Passwort“ (oder oben rechts auf deinen Namen → „Passwort ändern“). Trage dein aktuelles Passwort ein und das neue zweimal. Das neue Passwort braucht mindestens 10 Zeichen, mit Buchstaben und mindestens einer Ziffer, und muss sich vom aktuellen unterscheiden. Nach „Passwort ändern“ gilt es sofort. Das Passwort eines anderen Benutzers setzt ein Admin unter Benutzer → Benutzer öffnen → Stammdaten." },
  { id: "reklamationsgruende", title: "Reklamationsgründe pflegen", keys: /reklamationsgr[üu]nd|gr[üu]nde? (anlegen|[äa]ndern|pflegen|sortier|umbenenn|ausblend)|reihenfolge der gr[üu]nde|geht weiter|endet hier/i, answer: "Reklamationsgründe (Einstellungen → Reklamationen): die Gründe, aus denen ein Käufer reklamieren kann.\n• Neuer Grund: oben eintragen → „Grund anlegen“.\n• Reihenfolge: mit den Pfeilen nach oben oder unten schieben – so stehen sie zur Auswahl.\n• Name: ins Feld klicken, ändern, Feld verlassen (oder Eingabetaste).\n• „Lead geht an die nächste Station“: an = nach einer genehmigten Reklamation mit diesem Grund bekommt die nächste Station der Lieferkette den Lead; aus = der Lead endet hier.\n• „Zur Auswahl“: aus = der Grund wird nicht mehr angeboten; bestehende Reklamationen behalten ihn.\nJede Änderung wird sofort gespeichert. Das gilt als Voreinstellung – in der Lieferkette kannst du bei einer Station unter „Wenn der Kunde reklamiert“ für einzelne Gründe etwas anderes festlegen." },
  { id: "kooperationen", title: "Kooperationen (Verzeichnis der Partner)", keys: /kooperation|partner (anlegen|verzeichnis|pausier|aktivier)|(einen|neuen|den) partner (an|l[öo]sch|pausier|aktivier)|beim partner|zuordnung(en)? (anlegen|entfernen|[äa]ndern)/i, answer: "Kooperationen (Menü Organisation): dein Verzeichnis der Partner, mit denen du Leads austauschst.\n• Oben vier Zahlen: Partner, aktiv, angefragt, pausiert. Darunter Reiter nach Stand und eine Suche (Partner, Kategorie oder Feld).\n• „Kooperation anlegen“: Name und Richtung (wir liefern, der Partner liefert, beide Richtungen). Der Partner steht zuerst auf „Angefragt“.\n• Zeile anklicken klappt den Partner auf: Angaben ändern, festhalten, wie deine Lead-Kategorien und die Felder eines Leads beim Partner heißen, aktivieren, pausieren oder löschen.\n• Gut zu wissen: Die Seite ist ein Nachschlagewerk. Ausgeliefert wird über die Lieferkette und die Integrationen – was hier steht, ändert an der Auslieferung nichts." },
  { id: "integrationen-statistik", title: "Integrationen (Partner-Plattformen)", keys: /integrationen|affiliate|partnerkonto|aroundhome|wattfox|leadnodes|enpal|gohighlevel|provision|anerkannt|storniert|gutschrift|ausgezahlt|transaktion|zeitbasis|gesamtquote|pre-?ping|kontingent|nachschieben|wochenbestellung|wochenkontingent/i, answer: "Integrationen (Dashboard → Reiter „Integrationen“; hieß bis Version 376 „Statistik“):\n• Je Partnerkonto eine Karte: was aus den gelieferten Leads wurde. Oben ein Balken (PrePing abgelehnt, ohne Rückmeldung, offen, storniert, anerkannt).\n• „PrePing abgelehnt“ (hieß bis Version 377 „Abgelehnt“): Der Partner hatte den Kontakt schon und lehnt ihn sofort beim Senden ab – meist eine Dublette. Solche Leads zählen nicht auf die Bestellung.\n• Kontingent (seit Version 378): Auf jeder Karte trägst du ein, wie viele Leads der Partner bestellt hat – je Woche (Montag bis Sonntag), je Tag oder je Monat. Die Karte zeigt dann für den laufenden Zeitraum: Bestellt · Gesendet · PrePing abgelehnt · Angenommen und groß „noch nachschieben“ = bestellt − angenommen. Beispiel: 900 bestellt, 900 gesendet, 80 hatte der Partner schon → 820 angenommen → noch 80 nachschieben. Darunter steht, wie viele das am Tag sind. Das Kontingent zählt immer den laufenden Zeitraum, egal welcher Zeitraum oben gewählt ist. Die Leiste über den Karten zählt alle offenen Kontingente zusammen. Ändern und entfernen über „ändern“ an der Karte (Inhaber, Admin, Manager).\n• Block „Zustellung“: Geliefert · PrePing abgelehnt · Angenommen · Gesamtquote = anerkannt ÷ geliefert.\n• Block „Bewertung durch den Partner“: Offen (Anteil an den angenommenen) · Anerkannt und Storniert (Anteil an den bewerteten) · Provision mit Schnitt je anerkanntem Lead. Bewertet = offen + anerkannt + storniert.\n• Hinweise: „ohne Rückmeldung“ = angenommen, aber der Partner führt den Lead noch nicht. „Transaktionen ohne unsere Zustellung“ zählen in keinem Zähler; ihre Provision steckt in der Kachel Provision.\n• Zum Aufklappen: Direkt beim Partner eingeliefert (z. B. Haustür, nach Vertriebler und Tag) · Sparten beim Partner · Kampagnen (wie auf der Gutschrift) · Kontakte (Statusfilter, Suche, „Mehr anzeigen“) · Stornogründe.\n• Filter: Sparte, Von/Bis mit „Anwenden“, Schnellwahl (Heute bis Maximal) und „Zeitraum nach“: Zustelldatum (Standard), Transaktionsdatum, Bearbeitungsdatum oder Auszahlungsdatum. Alle Filter stehen in der Adresse – die Ansicht lässt sich verlinken. Standard: letzte 30 Tage.\n• Woher die Zahlen kommen: Aroundhome wird abgerufen (automatisch alle 15 Minuten und über „Aktualisieren“), WattFox meldet jede Änderung über die Tracking-URL. Leadnodes, Enpal und GoHighLevel lassen sich als Konto anlegen; ihr Rückkanal folgt.\n• Einrichten: Einstellungen → Integrationen → „Plattformen“. Dort je Konto den Käufer wählen, über den es beliefert wird." },
  { id: "dashboard", title: "Dashboard lesen (Übersicht & Integrationen)", keys: /dashboard|\bstart\b|operations overview|kennzahl|kpi|stundenverlauf|lead-puls|puls|preping|bestellverteilung|zeitraum|von.bis|zeitspanne|statistik|auswertung|annahmequote|auf einen blick/i, answer: "So liest du das Dashboard:\n• Zwei Reiter oben rechts: „Übersicht“ (von oben nach unten: Kennzahlen – Ausgelieferte Leads, Umsatz, Dubletten, Reklamationen, PrePing – → Bestellverteilung → Karte „Wo fließen die Leads?“ → Stundenverlauf → Lead-Puls) und „Integrationen“ (je Partnerkonto, was aus den gelieferten Leads wurde – mit eigenen Filtern für Sparte, Zeitraum und Zeitbasis). Zeitraum und Kategorie oben gelten für die Übersicht – auch der Lead-Puls zeigt nur Leads aus dem gewählten Zeitraum und der gewählten Kategorie.\n• Oben wählst du Zeitraum (Heute, Diese Woche, Gesamt …) und Kategorie – alle Bereiche darunter beziehen sich darauf. „Eigener Zeitraum“ öffnet Von/Bis-Felder mit Schnellwahl (Letzte 7/30/90 Tage, Letzter Monat, Quartal, Jahr); die Auswahl wird gemerkt. „Erstellt ab“ zählt alles ab einem Tag bis heute, „Erstellt vor“ alles vor einem Tag (der Tag selbst zählt nicht mit) – wie auf der Leads-Seite.\n• Kacheln: Ausgelieferte Leads (an Käufer übergeben), Umsatz, Dubletten, Reklamationen und PrePing abgelehnt (Käufer hat per PrePing vorab abgelehnt).\n• Stundenverlauf: Zahl über jedem Balken = Leads in dieser Stunde; roter Anteil = per PrePing abgelehnt. Klick auf einen Balken zeigt, welche Kategorie an welchen Kunden ging; „Ganzen Tag anzeigen“ listet alle Stunden.\n• Bestellverteilung: welche Bestellung wie viele Leads bekommen hat (Käufer, Lieferant, Kategorie, Weg, Geliefert, PrePing, Umsatz).\n• Lead-Puls: die neuesten Leads mit Status." },
  { id: "leads", title: "Leads", keys: /\blead(s)?\b|quick view|lead-seite|sammelaktion|import|csv|spalte|filter|leadansicht|status|hängend|haengend|dublette|fehlerhaft|zugewiesen|genehmigt|reklamiert|deaktiviert/i, answer: "Leads:\n• „Lead anlegen“ oder „Leads importieren“: erst die Lead-Kategorie wählen, dann die CSV-Datei ins Feld ziehen (oder klicken). Der Import kann rückgängig gemacht werden. Excel-Dateien vorher als CSV speichern.\n• „Testlead senden“: Die Auswahl zeigt die eingeschalteten Schnittstellen der Käufer (Benutzer → Käufer → Reiter „Integration“) und die Verbindungen aus Einstellungen → Integrationen. Bei einer Schnittstelle gibt sie die Kategorie vor; das Ergebnis steht direkt im Fenster. Zeigt eine Wattfox-Schnittstelle auf das Live-System, geht kein erfundener Lead raus – geprüft wird nur die Anmeldung. Schnittstellen der Käufer kann nur ein Administrator testen.\n• Status-Reiter (Zugewiesen, Reklamiert, Fehlerhaft, Deaktiviert, Hängend, Dubletten) und „Filter“ (Kategorie, Lieferant, Zeitraum). Rechts neben den Reitern: „Filter zurücksetzen“, „Filter speichern“ (mit Namen) und „Gespeicherte Filter“ – anklicken lädt, der Papierkorb löscht einen, darunter „Alle gespeicherten Filter löschen“.\n• Spalte „Typ“ zeigt die Kategorie als Kürzel (PV, WP, FEN …); „Spalten anpassen“ blendet Spalten ein/aus.\n• Leiste über der Tabelle – der Weg der Leads: „Leads gesamt“ (mit Balken, wo alle stehen) · „Heute neu“ (verglichen mit gestern bis zur selben Uhrzeit) · „Bereit zum Ausliefern“ (und wie alt der älteste wartende Lead ist) · „Ausgeliefert“ (letzte 7 Tage, heute, Summe der Preise). Eine Zahl „Reklamiert“ gibt es hier seit Version 377 nicht mehr – Reklamationen stehen unter „Reklamationen“ und als Reiter der Tabelle. Daneben die letzten 14 Tage als Säulen: die letzten 7 Tage gegen die 7 davor. Ein Klick auf eine Kachel oder Säule zeigt genau diese Leads; andere Filter werden dabei geleert.\n• Ist oben ein Zeitraum gewählt (z. B. „Gestern“), folgen die Kacheln ihm: Die zweite Kachel heißt dann wie der Zeitraum („Gestern“, verglichen mit vorgestern), „Bereit zum Ausliefern“ und „Ausgeliefert“ zählen nur die Leads aus diesem Zeitraum. Ein Klick auf eine Kachel behält den Zeitraum; „Leads gesamt“ nimmt ihn wieder weg.\n• „Erstellt zwischen …“, „Erstellt ab …“ und „Erstellt vor …“: Die Tage stehen direkt in der Zeile neben dem Zeitraum.\n• Spalte „Geliefert“: wie frisch der Lead ist – „vor 12 Min.“ mit grünem Punkt (unter 15 Minuten pulsiert er), „Heute 17:28“, „Gestern 16:58“; der genaue Zeitpunkt steht im Hinweis beim Überfahren. Vor dem Namen ein Kreis mit dem Kürzel in der Farbe der Kategorie; die Flagge nur bei Leads aus dem Ausland.\n• Unten: wie viele Leads gefunden sind, welche auf dieser Seite stehen, Seitenknöpfe und „Leads pro Seite“.\n• Hinweis unter der Leiste, wenn freigegebene Leads nicht rausgehen: keine Lieferkette für die Kategorie eingeschaltet → „Lieferkette einrichten“; die Auslieferung hakt → „API-Fehler ansehen“; es gibt eine Kette, aber keine Automation liefert von selbst aus → „Automation einrichten“ (Aktion „Automatisch ausliefern“) oder die Leads anhaken und von Hand ausliefern. „Diese Leads zeigen“ filtert die Tabelle darauf; das Kreuz blendet den Hinweis für drei Tage aus.\n• Auge = Quick View (Kontakt, Fachfelder, Log, Reklamation erfassen, jetzt ausliefern). Klick auf den Namen = Lead-Seite mit allem.\n• Lead-Seite oben: Kreis mit dem Kürzel in der Farbe der Kategorie, Kategorie, Status, Ort, wann der Lead eingegangen ist („vor 2 Std.“), Lieferant und die ID – ein Klick auf die ID kopiert sie. Rechts „Reklamation erfassen“, „Deaktivieren“, „Jetzt ausliefern“; darunter „Anrufen“, „E-Mail schreiben“ und „Kontakt kopieren“ (Name, Anschrift, Telefon und E-Mail auf einmal).\n• Weg des Leads in vier Schritten: Eingegangen → Geprüft → Ausgeliefert → nach dem Verkauf (Reklamationsfenster mit Restzeit als Balken, Reklamation oder „Fest verkauft“). „+1“ heißt: noch ein weiterer Käufer; „Angeboten – wartet auf Übergabe“: der Käufer hat ihn noch nicht übernommen. Haken = erledigt, leuchtender Ring = läuft gerade, ! = bitte ansehen, ✕ = gescheitert, gestrichelt = kommt noch.\n• Einkauf (Preis beim Lieferanten), Verkauf (angenommene und angebotene Auslieferungen), Erstattet (genehmigte Reklamationen) und Marge mit Anteil vom Verkauf. Käufer und Lieferanten mit eigenem Zugang sehen diese Zeile nicht.\n• Darunter links die Fachfelder als Kacheln („5 von 8 ausgefüllt“, leere Felder lassen sich einblenden; Feldnamen beginnen groß, z. B. „WP Gebäudetyp“ statt „wp_gebaeudetyp“, Werte ebenso: „Heizkörper“), das Gespräch mit Punkte-Balken, Kontakt (E-Mail und Telefon mit Kopier-Knopf) und Herkunft; rechts Auslieferung (Käufer, Ergebnis, Preis, Zeit), Reklamationen, Tags und Lead-Log.\n• Mehrere Leads anhaken → Sammelaktion unten (Ausliefern, Käufer zuordnen, Status setzen, Tag setzen).\nStatus: Neu = eingegangen · Genehmigt = geprüft, unverkauft · Zugewiesen = an Käufer ausgeliefert · Reklamiert = Reklamation genehmigt · Fehlerhaft = Daten ungültig · Hängend = wartet auf Liefertag/Kette · Dublette = bereits vorhanden." },
  { id: "kategorien", title: "Lead-Kategorien", keys: /kategori|sparte|fachfeld|typ\b|kürzel|farbe/i, answer: "Lead-Kategorien (Kategorien wie Photovoltaik, Wärmepumpe, Fenster, Treppenlifte, Barrierefreie Bäder, Alarmanlagen, Wintergärten, Elektrorollstühle, Rollatoren, Hörgeräte):\n• Links eine Kategorie wählen → Grundeinstellungen (Name, Kürzel, Farbe, Emoji, Preis, Mehrfachverkauf), Fachfelder (Text, Zahl, Auswahl, Ja/Nein …) und Datenharmonisierung.\n• Farbe und Emoji erscheinen überall dezent (Lead-Liste „Typ“, Dashboard-Chips und -Pillen, Karte, Quick View, Pipeline-Karten). Ohne eigenes Emoji schlägt die Software eines aus dem Namen vor („Vorschlag“).\n• „Neue Kategorie aus Spezifikation“: Parameterblatt hochladen, der Builder schlägt Fachfelder vor." },
  { id: "bestellungen", title: "Auslieferung (Bestellungen und ihre Lieferketten)", keys: /bestell|auftrag|liefertag|menge|leadpreis|auslieferung|sparten? (wählen|auswählen|einzeln)|alle sparten|leadsparte|wohin (gehen|geht) (die |der )?leads?/i, answer: "Auslieferung – so heißt der Menüpunkt seit Version 377 (vorher „Bestellungen“); dort legst du Bestellungen an und baust ihre Lieferketten:\n• „Bestellung anlegen“: Name, Käufer, zugelassene Lieferanten, eine oder mehrere Kategorien, Leadpreis, Menge, Liefertage/Uhrzeiten, Lieferpausen, Zusatzfilter.\n• Schritt 2 „Lieferkette“ (seit Version 376): Mit dem Speichern entsteht die Lieferkette der Bestellung von selbst – je Leadsparte eine. Station 1 ist die Bestellung: ihr Käufer zu ihrem Preis, mit ihren Lieferanten, ihrem Start, ihrem Gebiet und ihren Liefertagen. Darunter trägst du weitere Stationen ein – wohin der Lead geht, wenn Station 1 ihn nicht nimmt. Käufer, Preis und Lieferanten von Station 1 änderst du in der Bestellung; nach dem Speichern stehen sie auch in der Kette.\n• Mehrere Leadsparten (seit Version 379): Über der Kette steht „Für welche Sparten gilt diese Kette?“. Angehakt sind alle Sparten mit derselben Kette. Was du darunter festlegst (Station dazu, Preis, Schalter, Gebiet, Regeln, Reihenfolge, löschen), gilt für alle angehakten Sparten. „Alle … Sparten“ hakt alle an. Eine Sparte abwählen: Sie behält ihre Kette, folgt aber den Änderungen nicht mehr. Eine Sparte mit anderer Kette dazunehmen: Nach einer Nachfrage bekommt sie diese Kette – ihre eigenen weiteren Stationen werden ersetzt; Stationen mit demselben Käufer bleiben mit ihren Zahlen. Station 1 bleibt immer, wie sie ist. Sparten mit eigener Kette stehen darunter mit ihrem Weg und „Kette von … ansehen“ – dort gilt zunächst nur diese Sparte. Ein Feld-Filter auf ein Feld, das es in der anderen Sparte nicht gibt, geht nicht mit; das wird gemeldet.\n• Bestellübersicht (seit Version 379): Unter jeder Bestellung steht ihre Lieferkette – Station 1 (die Bestellung, grün), danach die weiteren Stationen mit Preis und am Ende, was mit einem Lead passiert, den niemand nimmt. Haben die Sparten verschiedene Ketten, steht je Weg eine Zeile mit den Namen der Sparten. Ausgeschaltete Stationen sind durchgestrichen. „Kette bearbeiten“ öffnet die Bestellung gleich bei der Lieferkette.\n• Der Bestellstart gilt immer: Vor dem Starttag geht kein Lead raus (auch bei „fortlaufend“). Eine Bestellung ohne gewählten Käufer liefert nicht.\n• Der Menüpunkt „Bestellungen“ öffnet die Bestellübersicht: oben Aktiv, Geliefert, Noch offen und Wert geliefert; je Bestellung Käufer und Lieferant, Kategorien, der Lieferstand als Balken (unbegrenzt gestreift), Preis je Lead und „Wert … von …“, Status Aktiv/Inaktiv. Startet eine Bestellung erst später, steht „startet am …“ am Namen – bis dahin bekommt sie keine Leads. „Bearbeiten“ öffnet die Bestellung, dort führt „Bestellübersicht“ zurück.\n• Leadmenge leer = unbegrenzt. Nur „Aktiv“ bekommt Leads. Leads werden automatisch passenden aktiven Bestellungen zugeordnet; „hängend“ heißt: wartet auf den nächsten Liefertag." },
  { id: "lieferkette", title: "Lieferkette (feste Verteilung)", keys: /lieferkette|kette|wasserfall|stop|weitergeben|round-robin|round robin|verteilmodus|verteil|reihenfolge|geo|bundesl/i, answer: "Lieferkette (feste Verteilung): Eine Kette legt fest, welche Kategorie von welchen Lieferanten an welche Kunden geht – in fester Reihenfolge.\n• Aufbau seit Version 370: oben eine Leiste mit Ketten (wie viele aktiv), Kunden in Ketten, Geschickt und Angenommen (mit Annahme in Prozent und Balken grün/rot) für den gewählten Zeitraum. Je Kategorie ein Kopf mit ihrem Emoji; jede Kette als Fluss „Von … → Kunde 1 → Kunde 2“ mit Balken für angenommen und abgelehnt. Gibt es noch keine Kette, zeigt die Seite an einem Bild, was eine Kette tut, und führt mit „Erste Lieferkette anlegen“ direkt zum Anlegen. In einer Kette stehen die Stationen der Reihe nach als Karten: Platz, Kunde, geschickt/angenommen/abgelehnt, Annahme, Preis (mit Komma eintippbar, „44,50“), Reklamationsfrist in Stunden und Höchstmenge. Unter jeder Station steht in einer Zeile, wann der Lead zur nächsten geht: das Gebiet passt nicht, der Kunde hat den Kontakt schon (Dublette), seine Höchstmenge ist erreicht, seine Schnittstelle lehnt ab – oder er reklamiert. Unter jeder Station steht ein Streifen „Aufklappen“ (seit Version 377; ein Klick auf den Namen geht auch) – er öffnet die Einstellungen der Station: die Reklamationsgründe (je Grund „erlaubt“ und „weitergeben“ oder „Lead endet hier“ – jede Änderung wird sofort gespeichert), das Gebiet (landesweit, Bundesländer, PLZ) und unter „Mehr Einstellungen“ die selteneren Filter. Unten: „Nächste Station hinzufügen“ und was passiert, wenn keine Station den Lead nimmt.\n• Kette einer Bestellung (seit Version 376): Station 1 ist die Bestellung. Sie zeigt Lieferant, Leadsparte, Preis, Menge, Start, Ende, Gebiet, Liefertage und Takt aus der Bestellung und lässt sich hier nicht löschen, ausschalten oder verschieben. Was nur ihren Käufer betrifft (Gebiet, Liefertag, Lieferpause, Dublette, Zugang pausiert), hält nur Station 1 auf – gibt es weitere Stationen, bekommen sie den Lead. Läuft die Bestellung selbst nicht (ausgeschaltet, noch nicht gestartet, beendet, Menge erreicht), geht über die ganze Kette nichts raus. Nur was an Station 1 geht, zählt zur Menge der Bestellung. Hat die Bestellung mehrere Leadsparten, hat jede ihre eigene Kette – eine neue Station kannst du mit einem Haken gleich in alle eintragen.\n• Ältere Ketten einer Bestellung bleiben, wie sie sind, bis du die Bestellung speicherst oder in der Kette „Aus der Bestellung übernehmen“ wählst (Hinweis oben in der Kette). Von selbst ändert sich nie, wer welchen Lead zu welchem Preis bekommt.\n• „Neue Lieferkette“: Kategorien wählen, Lieferanten wählen (alle oder nur bestimmte), Kunden in der gewünschten Reihenfolge mit Preis eintragen.\n• Der Lead geht zuerst an Kunde 1. Nimmt der ihn nicht (Gebiet, Tagesgrenze, Dublette, Ablehnung), geht er an Kunde 2 und so weiter.\n• Es wird nicht abgewechselt (kein Round-Robin): Passen mehrere Ketten zu einem Lead, kommt immer zuerst die Kette mit der kleineren Zahl bei „Reihenfolge“. Mit den Pfeilen in der Übersicht stellst du die Reihenfolge um.\n• Reklamationsgründe je Station auf „weitergeben“ stellen → bei genehmigter Reklamation geht der Lead an die nächste Station. Sind alle Stationen durch, ist die Kette „erschöpft“. Fehlen Gründe, legt „Standard-Gründe ergänzen“ die übliche Liste an (weitergegeben wird dabei nur bei „Dublette“ und „Zustellung fehlgeschlagen (API)“).\n• PLZ-Gebiete/Bundesländer je Station: nur passende Leads werden angeboten.\n• Unter „Aktivität“ siehst du je Stop, welche Leads angeboten, angenommen oder übersprungen wurden. Was nicht rausgeht, steht unter „API-Fehler“." },
  { id: "api-fehler", title: "API-Fehler: was beim Ausliefern hakt", keys: /api-?fehler|api fehler|api-?gesundheit|nicht ausgeliefert|ausliefer\w* (?:fehl|problem|hakt|geht nicht)|schnittstelle\w* (?:gest|fehl)|erneut ausliefern|kein abnehmer|lead\w* korrigier/i, answer: "API-Fehler (Menü „Analyse“): Hier steht alles, was beim Ausliefern hakt.\n• Oben „API-Gesundheit“: je Schnittstelle grün, gelb oder rot – mit der letzten Übergabe und dem letzten Fehler. Rot oder gelb wird es nur, wenn die Schnittstelle selbst hakt (kein Zugang, falsche Adresse, Störung, keine Antwort). Lehnt der Empfänger einzelne Leads wegen ihrer Angaben ab, läuft die Schnittstelle – das steht als „abgelehnt“ dabei. „Jetzt prüfen“ testet, ob die Empfänger erreichbar sind; dabei geht kein Lead raus.\n• Darunter die Leads, die nicht rausgegangen sind – mit dem Grund in einfachen Worten: Angaben falsch (zum Beispiel E-Mail-Adresse), vom Empfänger abgelehnt, Zugang oder Adresse der Schnittstelle falsch, Störung beim Empfänger, kein Abnehmer.\n• „Angaben fehlen“: Fehlt einem neuen oder freigegebenen Lead die E-Mail-Adresse, steht er hier schon, bevor er rausgeht. Hat die Kategorie eine Wattfox-Schnittstelle, stehen alle Pflichtangaben da, die fehlen: Anrede (bei Photovoltaik), Name, Straße, PLZ, Ort, Telefon, E-Mail. Gemeldet werden Leads der letzten 30 Tage. Nachtragen über „Korrigieren“ (die Anrede ist dort ein Auswahlfeld) – oder abhaken.\n• Anrede: Die Software liest sie aus dem Gespräch („Herr …“ oder „Frau …“ mit dem Nachnamen des Kunden) und trägt sie von selbst ein – auch bei vorhandenen Leads (Vermerk im Lead-Log). Fällt der Name im Gespräch nicht oder nicht eindeutig, bleibt sie leer.\n• Woher eine fehlende E-Mail-Adresse kommt: Der Dialer schickt sie nicht mit und im Gespräch wurde sie nicht genannt. Schickt der Dialer sie unter einem eigenen Namen (zum Beispiel „pv_email“), übernimmt die Software sie von selbst.\n• „Korrigieren“: Angaben des Leads ändern (das falsche Feld ist markiert) und mit „Speichern und ausliefern“ noch einmal losschicken.\n• „Erneut ausliefern“ schickt den Lead unverändert noch einmal los – auch mehrere auf einmal.\n• „Erledigt“ hakt ein Problem ab; scheitert derselbe Lead wieder, steht er wieder da.\n• Leads mit falscher E-Mail-Adresse, Rufnummer oder PLZ stehen schon vor dem Ausliefern hier.\n• „Welche Fehler gibt es?“ erklärt jede Art von Fehler." },
  { id: "automatisierung", title: "Automatisierung", keys: /automatis|regel|wenn|dann|sonst|aktion|auslöser|trigger/i, answer: "Automatisierung (Wenn → Dann → Sonst):\n• „Neue Automatisierung“: Auslöser (z. B. Lead erstellt, Reklamation genehmigt), Bedingungen (Feld, Operator, Wert) und Aktion (Lead freigeben, Status ändern, Kategorie ändern, Tag setzen, Webhook, E-Mail …). Optional ein SONST-Zweig.\n• Der Automatisierungsbuilder auf der Seite baut aus einem Satz eine Regel (pausiert) – danach prüfen und aktivieren.\n• „Protokoll“ zeigt jede Ausführung mit Ergebnis." },
  { id: "integrationen", title: "Integrationen & API", keys: /integration|api|schnittstelle|endpunkt|endpoint|webhook|token|builder|aroundhome|wattfox|ondialer|dialer/i, answer: "Integrationen:\n• Eingehend: Lieferanten schicken Leads per API (Token unter Benutzer → Lieferant → „Token erzeugen“; Beispiele unter Einstellungen → API-Dokumentation). Partner-Webhooks: /api/partner/wattfox, /api/partner/ondialer.\n• Ausgehend: Käufer bekommen Leads an ihren Endpunkt (Benutzer → Integration → Endpunkt, Vorlagen z. B. Aroundhome mit Sub-ID, Response-Mapping für Dublette/Ablehnung).\n• Einen eigenen Menüpunkt „Integrationen“ gibt es nicht mehr: Leads gehen über die Schnittstelle beim Käufer raus (Benutzer → Käufer → Reiter „Integration“), Bestellungen und Lieferketten nutzen genau sie. Ältere Verbindungen aus dem Integrationsbuilder stehen weiter unter Einstellungen → Integrationen. Fehler siehst du im Lead-Log (HTTP-Status + Antwort) und unter „API-Fehler“.\nTypische Ursachen: falscher Zugangsschlüssel (401/403), falsche Feldnamen (400/422), Endpunkt nicht erreichbar." },
  { id: "reklamation", title: "Reklamationen", keys: /reklam|frist|dublette|grund|genehmig|ablehn/i, answer: "Reklamationen (Seite „Reklamationen“):\n• Oben stehen vier Zahlen: was auf deine Entscheidung wartet, was überfällig ist (Prüffrist vorbei), wie viele genehmigt und wie viele abgelehnt wurden.\n• Die Liste hat Reiter nach Stand (Alle, Offen, In Prüfung, Genehmigt, Abgelehnt), eine Suche und „Filter“ (Grund, Kategorie, Lieferant, Prüffrist, erstellt ab/bis). Jede Zeile nennt Grund, Lead, Käufer, Stand und Prüffrist.\n• Zeile anklicken klappt die Reklamation auf: was der Käufer schreibt, was er bezahlt hat, der Verlauf. Dort änderst du die Prüffrist und entscheidest mit „Genehmigen“ oder „Ablehnen“.\n• Genehmigt: Der Lead ist „Reklamiert“; sieht die Lieferkette für diesen Grund „weitergeben“ vor, geht er an die nächste Station. Abgelehnt: Die Lieferung gilt wieder als angenommen und der Lead bekommt seinen Status von vorher zurück.\n• „Alle ablehnen“ / „Alle genehmigen“ entscheidet alle Reklamationen der Ansicht, die noch warten (offen und in Prüfung), auf einmal – auf demselben Weg wie einzeln.\n• Selbst erfassen: „Reklamation erfassen“ → Lead suchen → Grund wählen. Das geht auch auf der Lead-Seite.\n• Per API: Käufer sendet POST /api/reclaim mit Lead-Nummer und Grund innerhalb seiner Frist (Benutzer → Reklamation: Frist, automatisch annehmen).\n• Gründe pflegst du unter Einstellungen → Reklamationen (Name, Reihenfolge, „geht weiter“ ja/nein, zur Auswahl ja/nein). „CSV exportieren“ lädt die Reklamationen der Ansicht herunter." },
  { id: "emails", title: "E-Mails", keys: /e-mail|email|mail|smtp|willkommen|erinnerung/i, answer: "E-Mails (Kommunikation → E-Mails): Beim Anlegen eines Benutzers geht sofort eine Willkommensmail (Anmeldeadresse, Benutzername, Passwort); Erinnerungen nach 3 und 7 Tagen, solange er sich nicht angemeldet hat. Versandprotokoll mit Vorschau, „Jetzt senden“, „Abbrechen“; Vorlagen mit Platzhaltern und „Testmail an mich“. Echter Versand braucht SMTP_URL und SMTP_FROM beim Hosting – ohne SMTP wird nur simuliert." },
  { id: "email-versand-einrichten", title: "E-Mail-Versand einrichten (Brevo, Zeitüberschreitung, Testmail)", keys: /versand einrichten|e-?mail-?versand|brevo|api-?schlüssel|xkeysib|xsmtpsib|smtp-?schlüssel|testmail.*fehl|fehlgeschlagen|zeitüberschreitung|timeout|port.*gesperrt|gesperrt.*port|587|2525|465|absender einrichten|anbieter wählen/i, answer: "E-Mail-Versand einrichten (Einstellungen → E-Mail-Versand):\n• Empfohlen bei Railway und ähnlichen Hostern: Anbieter-Karte **„Brevo über HTTP“**. Dann braucht es nur den **API-Schlüssel** (in Brevo: SMTP & API → Reiter „API-Schlüssel“, beginnt mit `xkeysib-`), Absendername, Absenderadresse, Tageslimit, Häkchen „Versand einschalten“ → **Speichern** (der Knopf direkt im Abschnitt, nicht oben in der Kopfzeile) → **Testmail** an die eigene Adresse.\n• Warum HTTP: Railway und viele andere Hoster sperren die Mail-Ports (25, 465, 587, 2525) gegen Spam-Versand. Ein SMTP-Versuch läuft dort in eine Zeitüberschreitung – egal ob die Zugangsdaten stimmen. Die HTTP-Schnittstelle läuft über Port 443 wie eine normale Webseite und ist immer erreichbar.\n• Testmail sagt „Zeitüberschreitung“ oder „timeout“: Der Hoster sperrt den Mail-Port. Lösung: Anbieter auf „Brevo über HTTP“ umstellen und den API-Schlüssel eintragen.\n• Zwei verschiedene Schlüssel: SMTP = `xsmtpsib-…`, HTTP = `xkeysib-…`. Wird der falsche eingetragen, erklärt die Testmail das im Klartext.\n• Testmail sagt „Brevo 401“: Schlüssel falsch oder gelöscht – in Brevo neu erzeugen und hier eintragen. „Brevo 400: sender not valid“: Die Absenderadresse ist in Brevo nicht als Absender freigegeben (Brevo → Absender & Domains).\n• Domain prüfen: Der Knopf prüft SPF, DKIM und DMARC. Liegt das Postfach bei Google und wird über Brevo versendet, muss beides im SPF stehen: `v=spf1 include:spf.brevo.com include:_spf.google.com ~all`.\n• Posteingang (IMAP): Postfach der Absenderadresse, Port 993; bei Google `imap.gmail.com` mit einem App-Passwort aus dem Google-Konto.\n• Der Knopf „Änderungen speichern“ oben in der Kopfzeile gilt nur für System, Branding, Nutzungsbedingungen und API-Dokumentation – alle anderen Bereiche speichern über ihre eigenen Knöpfe am Abschnitt." },
  { id: "haustuer", title: "Haustür-Erfassung", keys: /haust|d2d|vertriebler|agentur|sub-id|subid|iframe|außendienst/i, answer: "Haustür-Erfassung (seit Version 377 nicht mehr im Menü – die Seite und ihre Daten gibt es weiter, erreichbar über die Adresse „?page=Haustür-Erfassung“): Vertriebler erfassen Kontakte zuerst bei uns (Schritt 1), dann im Aroundhome-iFrame (Schritt 2, Werte per Klick kopieren). Jeder Vertriebler hat eine Sub-ID von Aroundhome; ohne Sub-ID sieht er nur einen Hinweis.\n• „Zuweisung“: Kategorie (Pflicht für die Vorerfassung) und optional Käufer (dann sofort verkauft, ohne Bestellung/API).\n• „Agentur anlegen“ erzeugt einen Agenturleiter-Login, der nur seine Agentur sieht. Vertriebler anlegen = Login per E-Mail, Sub-ID gleich oder später, Sperren möglich.\n• Kennzahlen: Vorerfasst (bei uns), Bei Aroundhome, Qualifiziert, Offen, Storniert – abgeglichen je Sub-ID und Tag, Stand spätestens 15 Minuten." },
  { id: "pipeline", title: "Vertriebspipeline & Meta Ads", keys: /vertriebspipeline|pipeline|meta|facebook|instagram|kampagne|werbe|anzeige|kosten je lead|cpl|funnel|trichter|kunde geworden|gewonnen/i, answer: "Vertriebspipeline (Vertrieb → Vertriebspipeline): Leads aus Meta Ads mit Kampagne, Anzeigengruppe, Anzeige und Formular – plus jeder Schritt bis zum Kunden.\n• Einstellungen → Facebook-Verbindung: „Mit Facebook verbinden“ (Facebook-Login, braucht META_APP_ID/META_APP_SECRET beim Hosting) oder Seiten-Token einfügen. Danach kommen neue Leads über den Meta-Webhook sofort an, ohne Zapier; Kampagnen-Kennzahlen (Ausgaben, Reichweite, Klicks) werden stündlich geladen.\n• Formulare → Kategorie: welches Lead-Formular welche Lead-Kategorie bekommt.\n• Pipeline: Stufen Neu → Kontaktiert → Qualifiziert → Termin → Angebot → Kunde (oder Verloren); umbenennen/ergänzen unter Einstellungen → Stufen. Karten per Ziehen in die nächste Stufe; Klick auf eine Karte klappt sie in ihrer Spalte auf (die Spalte wird etwas breiter): oben Anrufen, nächste Stufe und die Werkzeuge (Wiedervorlage, Termin und Wert zeigen den aktuellen Stand direkt im Knopf; SMS, WhatsApp, E-Mail), darunter Infos und Notizen (mit Mikrofon) nebeneinander – alles auf einen Blick, die Karte bleibt kompakt; Schritte und Nachrichten lassen sich darunter aufklappen. Klick auf den Namen öffnet die Lead-Seite. Jeder Schritt wird mit Zeit und Person protokolliert.\n• Statistik: Kennzahlen, Funnel, Pipeline-Wert und die Tabelle „Kampagnen aus Meta“ (Budget, Ausgaben, Reichweite, Klicks, Leads, Kosten je Lead, Kunden, Kosten je Kunde) – Klick „Pipeline zeigen“ filtert das Board auf die Kampagne.\n• Reiter oben: Pipeline, Aufgaben, Termine, Statistik, Einstellungen (Stufen, Team & Ziele, Automatik, Facebook-Verbindung); bei Kaltakquise zusätzlich „Listen & Kontakte“." },
  { id: "wiedervorlagen", title: "Wiedervorlagen, Aufgaben & Termine", keys: /wiedervorlage|aufgabe|heute fällig|fällig|erledigt|verschieben|termin|kalender|einladung|ics|erinnerung|kalendereintrag/i, answer: "Wiedervorlagen & Termine (Vertriebspipeline → „Aufgaben“ und „Termine“):\n• An jeder Karte: „Wiedervorlage“ (Anrufen, E-Mail, Aufgabe, SMS, WhatsApp mit Datum/Uhrzeit, Zuständigem, Notiz). Aus dem Dialer entstehen sie automatisch: „Wiedervorlage“ → Rückruf, „Interessiert“ → „Angebot / Unterlagen schicken“, „Nicht erreicht“ → erneut versuchen (Automatik abschaltbar).\n• „Aufgaben“ (Reiter zwischen Pipeline und Termine): Überfällig, Heute, Morgen, Diese Woche – mit „Jetzt anrufen“ (Pipeline-Dialer), „Alle abtelefonieren“, Erledigt, Verschieben (morgen/3 Tage/1 Woche), Löschen. Die Karte zeigt die nächste Fälligkeit als Hinweis; Filter „Fällig“ im Board.\n• „Termin“ an der Karte: Datum, Dauer, Ort, Notiz – schiebt die Karte in die Stufe „Termin“, legt den Termin im Kalender an und schickt auf Wunsch die Einladung mit Kalendereintrag (ICS) per E-Mail. Die Erinnerung an den Kunden (E-Mail/SMS/WhatsApp, X Stunden vorher) läuft über die Automatik.\n• „Termine“: Wochenkalender (Mo–So) mit Terminen groß und Wiedervorlagen klein; Klick öffnet die Karte." },
  { id: "stufen", title: "Stufen der Pipeline anpassen", keys: /stufe|stufen|spalte|spalten|umbenennen|reihenfolge|neue stufe|stufe löschen/i, answer: "Stufen (Vertriebspipeline → Einstellungen → Stufen): Stufen umbenennen, Hinweis ändern, Reihenfolge per Pfeile, neue Stufe hinzufügen (bis 12) oder löschen – Eingang, „Kunde“ und „Verloren“ bleiben immer erhalten (umbenennbar). Gilt für alle drei Pipelines (Meta Ads, Kaltakquise, E-Mail); Leads gelöschter Stufen rutschen auf den Eingang. „Speichern“ wird erst aktiv, wenn sich etwas geändert hat; „Zurücksetzen“ verwirft die Änderung." },
  { id: "eingeschlafen", title: "Eingeschlafene Karten", keys: /eingeschlafen|schläft|keine bewegung|aufweck|aufwecken/i, answer: "Eingeschlafene Karten:\n• Eine Karte gilt als eingeschlafen, wenn X Tage (Automatik, Standard 5) nichts passiert ist – kein Stufenwechsel, keine Notiz, keine Nachricht, keine erledigte Aufgabe. Hinweis „💤 X Tage“ an der Karte, Filter „Eingeschlafen“ im Board.\n• Optional nimmt die Automatik eingeschlafene Kontakte mit E-Mail automatisch in eine Aufweck-Serie auf (einmal je Karte). Serie unter Automatik anlegen oder wählen.\n• Eingeschlafene Karten kühlen auch in der Einschätzung ab (siehe „Heiße Phasen“): −10 Punkte." },
  { id: "heisse-phasen", title: "Heiße Phasen: Heiß, Warm, Kalt an jeder Karte", keys: /heiße? phasen|\bheiss|\bheiß|\bwarm\b|\bkalt\b|lead-?punkte|\bpunkte|\bscore\b|scoring|temperatur|einschätzung|welche karte zuerst|priorität/i, answer: "Die Einstufung Heiß/Warm/Kalt wird an den Karten nicht mehr angezeigt – sie bewertete schon vorhandene Kontaktdaten (Telefon, E-Mail, Firma), sodass frisch hochgeladene Kontakte ohne jede Reaktion „Warm“ waren. Zum Priorisieren nutzt du die Filter „Eingeschlafen“, „Fällig“ und „Nicht zugeteilt“, den Anrufzähler an der Karte und die Stufe." },
  { id: "nachrichten", title: "SMS, WhatsApp & Einzel-E-Mail aus der Karte", keys: /\bsms\b|whatsapp|nachricht senden|einzel-e-mail|einzelmail|vorlage aus kampagne|textnachricht/i, answer: "Nachrichten aus der Karte (Vertriebspipeline → Karte öffnen → SMS / WhatsApp / E-Mail):\n• Vorlagen (Rückruf anbieten, Termin bestätigen, Terminerinnerung, Unterlagen, Angebot nachfassen, freier Text) mit Platzhaltern {{anrede}} {{nachname}} {{vorname}} {{firma}} {{termin}} {{absender}} – Vorschau vor dem Senden.\n• SMS geht über die eigene Rufnummer (Telefonie). WhatsApp: es öffnet sich WhatsApp mit vorausgefülltem Text, abschicken tust du dort. SMS gehen über sipgate. E-Mail: freier Text oder eine E-Mail aus einer Kampagne/Vorlage im Kampagnen-Design.\n• Jede Nachricht steht im Verlauf der Karte („Nachrichten“ und „Schritte“); die erste Nachricht zieht die Karte aus „Neu“ nach „Kontaktiert“. Sperrliste wird beachtet." },
  { id: "angebotswerte", title: "Angebotswerte, Pipeline-Wert & Umsatz", keys: /angebotswert|auftragswert|wert\b|umsatz|pipeline-wert|gewichtet|abschlussquote|euro/i, answer: "Angebotswerte & Umsatz:\n• An der Karte „Wert“ (Angebots-/Auftragswert in Euro). Steht als Pille an der Karte.\n• Statistik: Pipeline-Wert (offen), gewichtet nach Stufe (Neu 10 % … Angebot 90 %), Umsatz gewonnen (Stufe „Kunde“), Abschlussquote nach Anzahl und nach Euro, Verloren, Wert je Stufe, Umsatz je Vertriebler.\n• Einstellungen → Team & Ziele: Umsatz und offener Wert je Vertriebler im gewählten Zeitraum. CSV-Export enthält die Werte." },
  { id: "pipeline-reihenfolge", title: "Reihenfolge der Pipelines", keys: /reihenfolge.*pipeline|pipeline.*reihenfolge|karten.*reihenfolge|meta ads.*(zuerst|vorne|oben)|kaltakquise.*(zuerst|vorne)|e-mail-kampagne.*(zuerst|vorne)/i, answer: "Vertriebspipeline → Einstellungen → Stufen, ganz oben „Reihenfolge der Pipelines“: mit den Pfeilen E-Mail-Kampagne, Meta Ads und Kaltakquise nach oben oder unten schieben und „Reihenfolge speichern“. So stehen die Karten oben in der Vertriebspipeline; die erste ist beim Öffnen gewählt." },
  { id: "team-verteilung", title: "Team: Ziele, Zählung & Verteilregeln", keys: /tagesziel|ziel\b|ziele|zählung|team|verteilregel|verteilung|reihum|regel|plz-anfang|auslastung|nicht zugeteilt|zuteilen|anteil|50\/50|prozent.*vertriebler|je pipeline/i, answer: "Team (Vertriebspipeline → Einstellungen → Team & Ziele):\n• Je Vertriebler: Anrufe (Dialer), erreicht, Gesprächsminuten, Termine gesetzt, Abschlüsse, Umsatz, offene Karten mit Wert, Aufgaben heute/überfällig – gegen das Tagesziel (Anrufe, Termine, Abschlüsse je Tag, direkt in der Tabelle eintragen). Zeitraum Heute / 7 Tage / 30 Tage.\n• Verteilung neuer Leads: Aus (nur von Hand), Reihum (abwechselnd an alle), Nach Anteilen (Prozent je Vertriebler, z. B. 50/50 oder 70/30 – „Gleich aufteilen“ setzt gleiche Anteile) oder Nach Regeln: je Regel ein Vertriebler, PLZ-Anfänge (z. B. 6, 5), Kategorien, maximale offene Karten; erste passende Regel gewinnt, sonst reihum oder offen lassen.\n• Anders je Pipeline: unter der Verteilung kann jede Pipeline (Meta Ads, Kaltakquise, E-Mail-Kampagne) eine eigene Einstellung bekommen, z. B. nur die Kaltakquise 50/50 an Taner und Francesco; „Wie oben“ nimmt die allgemeine Einstellung. Gilt für neue Karten aus Meta, Listen, Lead-Finder und Posteingang ohne gewählten Vertriebler – und beim Übernehmen von Kontakten aus der E-Mail-Akquise in eine Pipeline (die Rückmeldung sagt, wie viele verteilt wurden; wer schon einen Vertriebler hat, behält ihn).\n• „Nicht zugeteilte jetzt verteilen“ und im Board per Mehrfachauswahl „Nach Regeln“." },
  { id: "mehrfachauswahl", title: "Suche, Filter, Mehrfachauswahl & CSV", keys: /suche|suchen|mehrfachauswahl|auswählen|markieren|mehrere karten|csv-export|export|herunterladen|excel/i, answer: "Board-Werkzeuge (Vertriebspipeline → Pipeline):\n• Suche über Name, Firma, Ort, PLZ, Telefon, E-Mail, Kampagne. Filter: Eingeschlafen, Fällig, Nicht zugeteilt.\n• „Auswählen“: Karten ankreuzen (alle sichtbaren/keine), dann Verschieben nach Stufe, Zuteilen an Vertriebler, Nach Regeln verteilen oder alle Ausgewählten anrufen (Power/Predictive-Liste).\n• „CSV“: alle Karten des aktuellen Filters (Zeitraum, Vertriebler, Kampagne/Liste) als Excel-taugliche Datei mit Stufe, Vertriebler, Angebotswert, Wiedervorlage, Termin und letzter Notiz." },
  { id: "pipeline-automatik", title: "Pipeline-Automatik: Serien, Antworten, Erinnerungen", keys: /automatik|stufe.*serie|angebot.*nachfass|nachfass-serie|anruf-ergebnis|antwort.*stufe|kontaktiert|terminerinnerung|automatisch.*serie/i, answer: "Automatik (Vertriebspipeline → Einstellungen → Automatik):\n• Eingeschlafene Karten: Tage ohne Bewegung + Aufweck-Serie.\n• Stufe → E-Mail-Serie: z. B. „Angebot“ → Nachfass-Serie (2 Mails, Ende sobald geantwortet). Entwürfe werden beim ersten Kontakt aktiv.\n• Anruf-Ergebnis → Serie/Wiedervorlage: „Interessiert“ schickt sofort die Angebots-Mail; Wiedervorlage/Nicht erreicht legen Aufgaben an (abschaltbar).\n• Antwort im Posteingang schiebt die Karte auf die gewählte Stufe (nur vorwärts, nie aus Kunde/Verloren).\n• Terminerinnerung an den Kunden per E-Mail/SMS/WhatsApp X Stunden vorher.\n• „Automatik jetzt ausführen“ prüft sofort; sonst läuft sie alle 15 Minuten im Hintergrund." },
  { id: "ki-builder", title: "KI-Vorlagen-Builder für E-Mails", keys: /ki-vorlage|ki-builder|ki vorlagen|e-mail bauen|serie bauen|serie per ki|per ki|ki-text|text erzeugen|beschreib|künstliche intelligenz|claude|generier|vorschläge|vorschreiben|vorlagen schreiben/i, answer: "KI-Vorlagen-Builder (E-Mail-Kampagnen):\n• Im Builder einer E-Mail: Reiter „KI-Vorlage“ – beschreibe in ein, zwei Sätzen, welche E-Mail du brauchst (Anlass, Zielgruppe, was der Empfänger tun soll), wähle Ziel (Termin, Rückruf, Angebot nachfassen, Infos, Aufwecken, Willkommen), Ton und Länge, optional Link für den Knopf und zweiter Betreff für den A/B-Test → „E-Mail bauen“ schreibt Betreff, Vorschautext und Bausteine; das Design bleibt. Danach wie gewohnt anpassen.\n• Im Kampagnen-Editor: „Serie per KI“ (oder „Neue Kampagne → Per KI beschreiben“) baut die ganze Serie: 2–4 E-Mails, Abstand in Tagen, Ende wenn geantwortet/geklickt/geöffnet. Jede E-Mail ist danach im Builder editierbar.\n• An der Pipeline-Karte: „KI-Text“ im Nachrichten-Fenster schreibt SMS/WhatsApp/E-Mail-Text aus einer kurzen Beschreibung.\n• Vorschläge: Der Builder schreibt Vorlagen vor – im Reiter „KI-Vorlage“ und bei „Serie per KI“ stehen fertige Vorschläge (Erstkontakt, Nachfassen nach Angebot, Aufwecken, Termin, Willkommen, Rückruf-Bitte, Infos & Unterlagen, Letzte Nachricht); ein Klick füllt nur die Beschreibung, Ziel, Ton und Länge aus – du kannst alles noch anpassen; gebaut wird erst mit „E-Mail bauen“ bzw. „Serie bauen“.\n• Vorlagen vorschreiben lassen: E-Mail-Kampagnen → Kampagnen → Knopf „Vorlagen“ oben rechts → „Vorlagen per KI schreiben“: Vorschläge ankreuzen, optional auf eine Lead-Kategorie zuschneiden (z. B. Photovoltaik) und Unterschrift angeben → fertige Vorlagen erscheinen im Vorlagen-Fenster (Knopf „Vorlagen“) und bei „Neue Kampagne → Aus Vorlage“; jede lässt sich im Builder anpassen.\n• Der Builder liefert immer eine ganze E-Mail: Überschrift, Anrede + Absätze, Aufzählung, Knopf, Grußformel, Signatur. Antwortet die KI zu kurz (nur eine Zeile), fragt der Builder einmal nach und ergänzt fehlende Teile aus dem Gerüst – der Hinweis nach dem Bauen zeigt Bausteine und Wörter.\n• Mit KI-Schlüssel (ANTHROPIC_API_KEY beim Hosting) schreibt die KI; ohne Schlüssel kommt ein regelbasierter Entwurf, der sich genauso anpassen lässt. In der Chat-Vorschau fragt der Browser einmal nach der KI-Freigabe." },
  { id: "telefon-nachtragen", title: "Dialer für Leads ohne Telefonnummer", keys: /keine telefonnummer|ohne nummer|nummer nachtragen|telefon nachtragen|dialer fehlt|anruf.*posteingang|posteingang.*anruf|aus der signatur/i, answer: "Dialer für Leads aus dem Posteingang / ohne Nummer:\n• Beim Anlegen eines Leads aus dem Posteingang wird die Telefonnummer aus der E-Mail-Signatur erkannt und vorausgefüllt („aus der E-Mail erkannt“); bei bestehenden Leads ohne Nummer gibt es das Feld „Telefon nachtragen“.\n• In der Pipeline hat jede Karte den Telefon-Knopf – ohne Nummer ist er gestrichelt: Klick fragt die Nummer ab, speichert sie an der Karte (Verlauf „Kontaktdaten“) und startet sofort den Anruf. In der geöffneten Karte heißt der Knopf dann „Nummer + Anrufen“." },
  { id: "posteingang", title: "Posteingang: Antworten lesen, KI-Einordnung, Filter", keys: /posteingang|antworten lesen|antwort.*kampagne|kampagne.*filter|filter.*kampagne|abholen|imap|ungelesen|prüfen|einordnung|einordnen|abwesenheit|interessiert|zeitraum.*posteingang|posteingang.*zeitraum|datum.*filter|filter.*datum/i, answer: "Posteingang (E-Mail-Kampagnen → erster Reiter ganz links, öffnet sich zuerst):\n• Oben die Ordner: Alle, Ungelesen, Antworten (auf Serien), Nicht zugeordnet (Absender, die noch keinem Lead in der Pipeline zugeordnet sind), Archiv, Gesperrt – jeweils mit Anzahl. Rechts daneben die Kampagnen-Auswahl („Alle Kampagnen“ oder eine Serie, dann erscheint ein Hinweis mit „Filter entfernen“) und „Aktualisieren“ (liest das Postfach).\n• Links die schmale Liste: Suchfeld oben, Nachrichten nach Heute / Gestern / Diese Woche / Älter gruppiert, mit Absender-Kürzel, Betreff, Vorschau und kleinen Merkern (Antwort auf welche Kampagne, Stufe in der Pipeline, Nicht zugeordnet, Abgemeldet, Gesperrt). Ungelesene haben einen farbigen Balken am Rand.\n• Rechts die Nachricht groß: Absender, Betreff, Hinweise (z. B. „In der Pipeline: Termin bei Taner“ als Link), darunter die Knöpfe Als Lead in Pipeline / Stufe setzen, Antworten, Sperren bzw. Entsperren, Archivieren. Das Lead-Formular klappt direkt unter den Knöpfen auf (Telefon aus der Signatur wird erkannt).\n• KI prüft jede Antwort beim Aktualisieren: Beschwerde, Abmeldewunsch, Interessiert, Frage oder Abwesenheitsnotiz. Eindeutige Beschwerden und Abmeldungen werden automatisch gesperrt (Hinweis „automatisch gesperrt“ mit Zitat an der Nachricht, Unterliste Beschwerden/Abmeldungen in der Sperrliste, Serie gestoppt); unsichere Fälle landen im Ordner „Prüfen“ mit den Knöpfen „Sperren“ und „Ist in Ordnung“. „Interessiert“ wird als Notiz an die Pipeline-Karte geschrieben, Abwesenheitsnotizen nur markiert. Schalter unter Einstellungen → E-Mail-Versand → „KI prüft jede Antwort“ (an/aus, automatisch sperren oder nur markieren). Ein Fehlgriff: „Entsperren“.\n• Sortierung (ganz links in der Leiste): Neueste zuerst, Älteste zuerst oder nach Einordnung – „Interesse zuerst“ gruppiert die Liste von Interessiert über Frage, Sonstiges, Abwesenheitsnotiz und Abmeldewunsch bis Beschwerde, „Beschwerde zuerst“ umgekehrt; jede Gruppe zeigt ihre Anzahl, die Wahl wird gemerkt.\n• Filter daneben: KI-Einordnung (Beschwerde, Abmeldewunsch, Interessiert, Frage, Abwesenheitsnotiz, Sonstiges, Automatisch gesperrt, Zu prüfen, Ohne Einordnung), Zeitraum (Gesamt, Heute, Gestern, Letzte 7 Tage, Letzte 30 Tage, eigener Von/Bis) und Kampagne – alle kombinierbar; „Filter entfernen“ setzt die Filter zurück.\n• Antwortfeld ganz unten; Strg + Enter sendet. „Antworten“ springt dorthin.\n• Auf dem Handy: erst die Liste, nach dem Antippen die Nachricht mit „Zurück zur Liste“.\n• „Aktualisieren“ liest das Postfach (Einstellungen → E-Mail-Versand → IMAP)." },
  { id: "werbung-ordner", title: "E-Mails landen im Werbung-Ordner oder im Spam", keys: /werbung|promotions|spam|junk|landet nicht im posteingang|zustellbarkeit|nicht angekommen|kommt nicht an|posteingang des empfängers|reiter werbung/i, answer: "E-Mails landen bei Gmail unter „Werbung“ oder im Spam:\n• Woran Gmail Werbung erkennt: Logo-Bild, farbiger Knopf, Kasten-Layout, ein Zählpixel für Öffnungen und Links, die über eine fremde Adresse umgeleitet werden. Genau das hat eine Kampagnen-Mail standardmäßig.\n• Lösung: Im Builder unter „Design“ den Schalter **„Persönlich senden“** einschalten. Dann geht die E-Mail ohne Logo, ohne Kasten, ohne farbigen Knopf (wird ein Textlink) und ohne Messung raus – sie sieht aus wie von Hand geschrieben und landet viel öfter im normalen Posteingang. Für Kaltakquise ist das die bessere Wahl; Öffnungs- und Klickraten gibt es dann allerdings nicht mehr.\n• Was sonst hilft: kurz schreiben, keine Werbesprache („GRATIS!!!“, viele Ausrufezeichen), höchstens ein Link, keine Bilder, Absendername als echter Mensch (z. B. „Taner von Tanesco Digital“). SPF, DKIM und DMARC müssen grün sein (Einstellungen → E-Mail-Versand → Domain prüfen).\n• Am Anfang langsam versenden: die ersten Tage 20–30 Mails, dann steigern. Ein frischer Absender, der sofort hunderte Mails schickt, wird aussortiert.\n• Antworten sind das stärkste Signal: Sobald jemand antwortet, landen weitere Mails an diese Person im Posteingang.\n• An die eigene Adresse zu testen führt in die Irre – Gmail ist bei Mails misstrauisch, die scheinbar von einem selbst kommen. Lieber an eine fremde Adresse testen." },
  { id: "kontakte-pipeline", title: "Kontakte aus der E-Mail-Akquise in die Pipeline übernehmen oder verschieben", keys: /pipeline übernehmen|in die pipeline|nicht in der pipeline|nur e-?mail|pushen|übernehmen.*pipeline|verschieben.*pipeline|pipeline.*verschieben|tauchen nicht auf|erscheinen nicht|stufe wählen|welche stufe|knopf.*aus|lässt sich nicht übernehmen|funktioniert nicht.*pipeline/i, answer: "Listen, die du **im Kampagnen-Editor** hochlädst, landen bewusst **nicht** sofort in der Vertriebspipeline – sonst wäre das Board nach jedem Upload voll mit Adressen, die noch niemand angefasst hat.\n• Diese Kontakte stehen unter E-Mail-Kampagnen → Kontakte. Die Spalte „Pipeline“ zeigt „nur E-Mail“ oder die Pipeline, in der der Kontakt steht (E-Mail-Kampagne, Kaltakquise, Meta Ads). E-Mail-Serien erreichen alle ganz normal.\n• **Übernehmen:** in der Spalte ganz links ankreuzen (oder oben alle auf einmal), dann die **Ziel-Pipeline** („E-Mail-Kampagne“ oder „Kaltakquise“) und die **Stufe** wählen und „In die Vertriebspipeline übernehmen“ klicken. Die Kontakte landen in genau dieser Pipeline und Stufe. Eine Verteilung an Vertriebler gibt es hier nicht – das passiert in der Pipeline.\n• **Verschieben:** Steht ein Kontakt schon in einer anderen Pipeline (z. B. Kaltakquise, weil die Liste damals direkt ins Board ging), wird er in die gewählte Pipeline **verschoben** – der Knopf ist jetzt immer aktiv. Steht er schon in der Ziel-Pipeline, wird nur die Stufe gesetzt. Die Rückmeldung sagt, was passiert ist (neu übernommen, verschoben, umgestuft, unverändert); im Verlauf der Karte steht „Aus der Pipeline „Kaltakquise“ in die Pipeline „E-Mail-Kampagne“ verschoben“.\n• **Anklicken:** Jede Zeile öffnet die Lead-Seite. **Löschen:** das ✕ am Zeilenende löscht einen Kontakt, ausgewählte Kontakte löscht der rote Knopf „Löschen“ – Kunden bleiben erhalten." },
  { id: "email-kontakte", title: "Kontakte der E-Mail-Akquise (eigene Lead-Liste)", keys: /kontakte.*kampagne|lead-?liste|eigene liste|wer steckt|wer ist in der kampagne|was ist passiert|reaktion|geöffnet.*liste|übersicht.*kontakte|akquise-?liste/i, answer: "Kontakte (E-Mail-Kampagnen → Reiter „Kontakte“): die eigene Lead-Liste der E-Mail-Akquise – getrennt von den Leads, die verkauft werden.\n• Je Zeile ein Kontakt mit: Name, Firma, E-Mail, aus welcher Liste er kommt, in welchen Kampagnen er steckt, was zuletzt passiert ist, wie viele Mails er bekommen hat, seine Stufe in der Pipeline, der Vertriebler und das Anlage-Datum.\n• „Zuletzt“ zeigt die stärkste Reaktion: Geantwortet vor Geklickt vor Geöffnet vor Gesendet; dazu Abgemeldet und Unzustellbar (Bounce). Daneben steht das Datum.\n• Filterleiste darunter mit Anzahl je Reaktion – ein Klick zeigt nur diese Gruppe, ein zweiter hebt den Filter auf.\n• Oben: Suche (Name, Firma, E-Mail, Ort, Liste), Herkunft, Liste, Kampagne und Vertriebler. „Filter entfernen“ setzt alles zurück.\n• Herkunft: Standard ist „Listen & E-Mail-Kampagnen“ – hochgeladene Listen (Kaltakquise, Lead-Finder) und Kontakte aus E-Mail-Kampagnen. Kontakte, die von selbst hereinkommen (Meta Ads, aus dem Posteingang angelegt), stehen hier nicht dazwischen; ein Hinweis zeigt, wie viele es sind, „Anzeigen“ (oder Herkunft „Meta Ads, Posteingang & Co.“) blendet sie ein – in der Spalte „Liste“ steht dann, woher sie kommen. Zu Hause sind sie in der Vertriebspipeline.\n• Klick auf den Namen öffnet die Lead-Seite mit dem ganzen Verlauf: E-Mails, Notizen, Aufgaben, Anrufe.\n• Hinweis: Wer in keiner Kampagne steckt, steht unter „Noch nichts“ – das sind frisch hochgeladene Kontakte." },
  { id: "gesendet", title: "Gesendet: verschickte E-Mails ansehen und filtern", keys: /gesendet|gesendete|verschickt|versendet|was wurde gesendet|ausgang|postausgang|sent/i, answer: "Gesendet (E-Mail-Kampagnen → Posteingang → Ordner „Gesendet“):\n• Zeigt alles, was rausgegangen ist: Kampagnen-Mails aus den Serien, Antworten, die du im Posteingang geschrieben hast, und Einzel-E-Mails aus einer Pipeline-Karte.\n• Filter oben: Art (Alle, Kampagnen, Antworten, Einzeln – jeweils mit Anzahl), Kampagne, Zeitraum (Gesamt, Heute, Letzte 7 Tage, Letzte 30 Tage) und ein Suchfeld über Adresse, Betreff und Kampagnenname.\n• Jede Zeile zeigt Betreff, Empfänger, Kampagne bzw. Absender und die Uhrzeit. Ist eine Mail fehlgeschlagen oder nur simuliert, steht das als roter Hinweis daneben.\n• **Vorschau:** Ein Klick auf die Zeile klappt die E-Mail so auf, wie sie rausging (Kampagnen-Mails werden aus dem Schritt und den Empfängerdaten nachgebaut).\n• **Tracking je Mail:** Unter jeder Kampagnen-Mail stehen drei Marken – Geöffnet, Geklickt, Geantwortet – jeweils mit Uhrzeit (oder „Nicht geöffnet“ usw.). Dazu ein Reaktions-Filter über der Liste: Geöffnet, Geklickt, Geantwortet, Noch nicht geöffnet, Unzustellbar, Abgemeldet – mit Zahlen.\n• Der Name des Empfängers ist verlinkt und öffnet die Lead-Seite." },
  { id: "posteingang-aufraeumen", title: "Posteingang: nur bekannte Kontakte holen, aufräumen, eigenes Kampagnen-Postfach", keys: /aufräumen|aufraeumen|alte mails|fremde mails|newsletter im posteingang|rechnungen im posteingang|nur bekannte|alles geladen|lädt alle|eigenes postfach|kampagnen-?postfach|vertrieb@|absender übernehmen|absender auf bestehende/i, answer: "Der Posteingang soll nur Antworten auf deine Kampagnen zeigen – nicht dein ganzes Postfach.\n• **Schalter „Nur Antworten von bekannten Kontakten holen“** (Einstellungen → E-Mail-Versand → IMAP, standardmäßig an): Beim Abgleich werden nur Mails von Kampagnen-Empfängern und Leads geladen. Rechnungen, Newsletter und Fremde werden übersprungen (der Abgleich meldet, wie viele).\n• **Aufräumen** (E-Mail-Kampagnen → Posteingang → Knopf „Aufräumen“): „Nur Fremde entfernen“ löscht alle Mails ohne Lead und ohne Kampagne – z. B. alles, was vor dem Umzug auf ein eigenes Postfach mitgeladen wurde. „Alles entfernen“ leert den Posteingang komplett; Sperrliste und „Gesendet“ bleiben.\n• **Eigenes Kampagnen-Postfach** (empfohlen): z. B. vertrieb@ deiner Domain anlegen, in den E-Mail-Einstellungen als Absender, „Antwort an“ und IMAP-Benutzer eintragen. Dann landen dort nur Kampagnen-Antworten.\n• **Absender auf bestehende Kampagnen übernehmen** (E-Mail-Einstellungen, unter den Absenderfeldern): schreibt den gespeicherten Absender in alle vorhandenen Kampagnen – sonst behalten laufende Kampagnen ihre alte Adresse. Neue Kampagnen nehmen den Absender automatisch." },
  { id: "pipeline-kontakte", title: "Vertriebspipeline: Reiter „Kontakte“ und Karten löschen", keys: /kontakte.*pipeline|pipeline.*kontakte|liste statt karten|alle kontakte der pipeline|karte löschen|karten löschen|lead löschen|leads löschen|aus der pipeline entfernen|mehrere löschen/i, answer: "Vertriebspipeline:\n• **Reiter „Kontakte“**: alle Kontakte der gewählten Pipeline (Meta Ads, Kaltakquise oder E-Mail-Kampagne) als Liste – auch ohne E-Mail-Adresse – mit Telefon, Ort, Herkunft (Liste oder Meta-Kampagne), letzter E-Mail-Reaktion, Stufe und Vertriebler. Filter: Suche, Liste, E-Mail-Kampagne, Stufe, Vertriebler, Reaktion. Klick auf die Zeile öffnet die Lead-Seite.\n• **Auswahl**: ankreuzen → „Stufe setzen“, „Zuteilen an“ oder „Löschen“ für alle markierten Kontakte.\n• **Karten löschen**: Karte aufklappen → Papierkorb oben rechts in der Karte; oder im Board „Auswählen“ → mehrere Karten ankreuzen → „Löschen“ in der Leiste. Gelöscht werden nur Vertriebskontakte samt Verlauf, Aufgaben und Notizen – Verkaufs-Leads bleiben (die löscht man auf der Leads-Seite). Das lässt sich nicht rückgängig machen.\n• Angeklickte Karten und die aktive Pipeline oben sind im hellen Design rot, im dunklen lila hervorgehoben." },
  { id: "stufen-je-pipeline", title: "Jede Pipeline mit eigenen Stufen", keys: /eigene stufen|stufen je pipeline|stufen pro pipeline|pipeline gestalten|individuell gestaltbar|stufen ändern|stufen anpassen|standard-?stufen|stufen zurücksetzen/i, answer: "Jede der drei Pipelines (Meta Ads, Kaltakquise, E-Mail-Kampagne) kann eigene Stufen haben:\n• Vertriebspipeline → Pipeline oben wählen → Einstellungen → „Stufen“. Dort steht, ob die Pipeline eigene Stufen hat oder noch die Standard-Stufen nutzt.\n• Oben rechts im Editor wählst du, wofür du speicherst: „Nur für diese Pipeline“ (Standard) oder „Als Standard für alle Pipelines“ – der Standard gilt für jede Pipeline, die keine eigenen Stufen hat.\n• „Standard nutzen“ verwirft die eigenen Stufen einer Pipeline wieder. Karten in Stufen, die es danach nicht mehr gibt, rutschen auf den Eingang.\n• Eingang, „Kunde“ und „Verloren“ bleiben in jeder Pipeline erhalten. Verschieben, Lead-Seite, Kontakte-Reiter und Automatik richten sich immer nach den Stufen der Pipeline, zu der ein Kontakt gehört." },
  { id: "termine-aufgaben", title: "Termine & Aufgaben in der Vertriebspipeline", keys: /aufgaben|wiedervorlage|termine|terminkalender|kalender|fällig|überfällig/i, answer: "Vertriebspipeline → Reiter „Termine & Aufgaben“: ganz oben vier Zahlen – überfällig, heute fällig, Termine heute, diese Woche. Darunter der Wochenkalender mit Terminen und Wiedervorlagen (Klick öffnet die Karte), darunter die Aufgaben nach Fälligkeit – überfällig, heute, morgen, diese Woche – mit Anrufen, Erledigen und Verschieben. Der Knopf „Jetzt anrufen“ ist nur bei Überfälligem kräftig rot; „Alle abtelefonieren“ ruft Überfälliges und Heutiges nacheinander an. Die Zahl am Reiter zeigt, wie viele Aufgaben heute fällig sind. Einen eigenen Reiter „Aufgaben“ gibt es nicht mehr." },
  { id: "signatur-anhaenge", title: "Signatur – in Kampagnen, Antworten und Einzel-E-Mails – und Anhänge", keys: /signatur|footer.*antwort|unterschrift|anhang|anhänge|datei anhängen|dateien anhängen|pdf mitschicken|angebot mitschicken|attachment|signatur.*kampagne|kampagne.*signatur/i, answer: "Eine Signatur für alles: Kampagnen-Mails, Antworten aus dem Posteingang und freie E-Mails aus einer Pipeline-Karte bekommen automatisch deine **Signatur**:\n• **Kampagnen**: Jede E-Mail einer Kampagne hängt die Signatur ans Ende an – auch bei Kampagnen, die schon vorher angelegt waren (sie wird beim Versand aus den Einstellungen geholt, nicht in die Kampagne kopiert). Im Builder siehst du sie in der Vorschau; unter „Design“ lässt sie sich je Kampagne abschalten. Ein alter Baustein „Signatur“ wird durch die Signatur aus den Einstellungen ersetzt.\n• Einstellungen → E-Mail-Versand → „Signatur für Antworten“: Grußformel, Name, Position, Telefon, E-Mail, Webseite; Haken für Logo und für Firma + Adresse (die kommen aus Einstellungen → Branding → Fußzeile). Rechts siehst du live, wie es beim Empfänger aussieht. Haken „aktiv“ weg = keine Signatur.\n• **Anhänge**: Im Antwortfeld unten „Anhang“ klicken (oder mehrere Dateien auf einmal wählen). Bis zu 5 Dateien, je höchstens 7 MB, zusammen 15 MB. Vor dem Senden lassen sich einzelne wieder entfernen. Im Ordner „Gesendet“ steht bei der Antwort, welche Dateien mitgingen.\n• Kampagnen-Mails nutzen weiterhin die Fußzeile aus dem Builder – die Signatur gilt nur für persönliche Antworten und Einzel-E-Mails." },
  { id: "glocke", title: "Glocke: Was ist auf der Plattform passiert? (Tagesverlauf)", keys: /glocke|benachrichtigung|mitteilung|verlauf der plattform|was ist passiert|tagesverlauf|aktivität|protokoll|wer hat was gemacht|roter punkt/i, answer: "Die Glocke oben rechts zeigt, was auf der Plattform passiert ist – nicht als Flut einzelner Meldungen, sondern als **Tagesverlauf**:\n• Je Tag eine Zeile mit Zusammenfassung, z. B. „Heute · 120 neue Kontakte · 14 Anrufe · 2 Leads verkauft“. Klick auf den Tag klappt die Arten auf (Anrufe, neue Leads, Gespräche abgehört, E-Mails gesendet, Antworten, Bestellungen, Reklamationen, Karten verschoben …), Klick auf eine Art zeigt die einzelnen Einträge mit Uhrzeit, Details und Lead-Nummer (klickbar).\n• Mitgeschrieben wird: Listen-Uploads (mit Zahlen), neue Leads (Meta Ads, Haustür, Posteingang, Test), Anrufe aus dem Dialer samt Ergebnis, abgehörte Aufzeichnungen (sobald der Player startet), Gesprächsbewertungen, verkaufte Leads (Auslieferung an einen Käufer), Bestellungen, Reklamationen, Karten-Verschiebungen in der Pipeline, Übernahmen aus der E-Mail-Akquise, gesendete Kampagnen-E-Mails (je Kampagne zusammengezählt), Antworten im Posteingang, Kampagnenstarts und rückgängig gemachte Uploads.\n• Die Zahl an der Glocke zeigt, wie viele Einträge seit deinem letzten Öffnen dazugekommen sind (gemerkt in diesem Browser). Die Glocke lädt sich jede Minute von selbst nach." },
  { id: "upload-verlauf", title: "Upload-Verlauf: was wurde wann hochgeladen, rückgängig machen", keys: /upload-?verlauf|verlauf.*upload|rückgängig|zurücknehmen|versehentlich hochgeladen|falsche liste|wieder löschen|wer hat hochgeladen|wann hochgeladen/i, answer: "Upload-Verlauf (Vertriebspipeline → Kaltakquise → „Listen & Kontakte“, und E-Mail-Kampagnen → „Kontakte“):\n• Jeder Upload steht dort mit Datum, Uhrzeit, Listenname, wer ihn gemacht hat und woher er kam (Kaltakquise oder E-Mail-Kampagne).\n• Daneben die Zahlen: wie viele Kontakte neu angelegt, wie viele vorhandene aktualisiert wurden – und wie viele davon es noch gibt.\n• **Rückgängig** entfernt genau die Kontakte, die bei diesem Upload **neu** entstanden sind. Kontakte, die dabei nur ergänzt wurden, bleiben – die gab es ja vorher schon. Kunden bleiben ebenfalls erhalten. Vor dem Löschen kommt eine Rückfrage mit der Anzahl.\n• Ein zurückgenommener Upload bleibt im Verlauf stehen, grau und mit Datum – damit nachvollziehbar bleibt, was passiert ist.\n• Hinweis: Lädst du einen Kontakt, den es schon gibt, in einer neuen Liste hoch, wechselt er in diese neue Liste – sonst würde er in der Zielgruppe der neuen Kampagne fehlen. Jeder Upload hat „Umbenennen“: die Kontakte genau dieses Uploads kommen in eine Liste mit dem neuen Namen – praktisch, wenn zwei Dateien versehentlich unter demselben Listennamen hochgeladen wurden. Beim Hochladen nimmt die Software als Listennamen jetzt immer den Namen der gewählten Datei." },
  { id: "listen-ansehen", title: "Hochgeladene Listen ansehen", keys: /liste ansehen|listen ansehen|was ist in der liste|inhalt der liste|wer bekommt|empfänger sehen|kontakte der liste|liste prüfen|liste anschauen/i, answer: "Listen ansehen:\n• In der Kaltakquise-Pipeline: Vertriebspipeline → „Kaltakquise“ → Reiter „Listen & Kontakte“. Unter jeder Liste steht der Knopf „Ansehen“ – er klappt eine Tabelle mit allen Kontakten auf: Name, Firma, Telefon, E-Mail, Ort, Stufe und die Zusatzspalten aus der Datei. Oben rechts ein Suchfeld.\n• Vorschau mit echten Daten: Sobald eine Zielgruppe steht, zeigen die Vorschauen im Ablauf und im Builder die E-Mail mit den Daten des ersten Kontakts statt mit „Max Muster“ – so siehst du vor dem Versand, ob die Platzhalter stimmen. Im Builder lässt sich oben über „Anzeigen mit“ ein anderer Kontakt wählen.\n• Im Kampagnen-Editor: Zielgruppe „Liste“ wählen – darunter stehen alle hochgeladenen Listen mit Anzahl der Kontakte und wie viele davon eine E-Mail-Adresse haben (nur die bekommen die Serie). Ein Klick wählt die Liste als Zielgruppe, „Ansehen“ zeigt die Kontakte, „Löschen“ entfernt die Liste.\n• Liste löschen (im Kampagnen-Editor oder unter „Listen & Kontakte“): Die Kontakte dieser Liste werden mitgelöscht, samt Aufgaben, Notizen und Nachrichten. **Kunden bleiben erhalten** – sie verlieren nur die Zuordnung zur Liste. Rückfrage vor dem Löschen; rückgängig machen geht nicht.\n• Unter der Tabelle stehen die Platzhalter dieser Liste, z. B. {{branche}} – die kannst du im Builder in Betreff und Text einsetzen." },
  { id: "liste-zur-kampagne", title: "Hochgeladene Listen zu einer E-Mail-Kampagne hinzufügen", keys: /liste.*(kampagne|hinzufüg)|listen.*(kampagne|hinzufüg)|mehrere listen|liste hinzufügen|kampagne.*liste|weitere liste/i, answer: "Eine Kampagne kann mehrere Listen haben. Im Kampagnen-Editor unter Zielgruppe → „Liste“ klickst du bei jeder gewünschten Liste auf „Zur Kampagne hinzufügen“ und dann auf „Speichern“ – bei einer laufenden Kampagne werden die Kontakte dabei sofort aufgenommen. Für eine fertige oder laufende Kampagne gibt es den Knopf „+ Liste“ in der Kampagnenübersicht und „Liste hinzufügen“ auf der Kampagnenseite: Läuft die Kampagne schon, werden die Kontakte sofort aufgenommen und bekommen die Serie ab der ersten E-Mail – wer schon dabei oder gesperrt ist, wird übersprungen. Im Entwurf kommen sie beim Start dazu. In der Empfängertabelle steht bei jedem Kontakt, aus welcher Liste er kommt. Lädst du später weitere Kontakte in eine Liste hoch, die in einer laufenden Kampagne steckt, werden sie automatisch aufgenommen. Bei jeder Kampagne steht, wie viele Kontakte ohne E-Mail-Adresse sind (die bekommen nichts) und wie viele noch nicht aufgenommen sind – „Jetzt aufnehmen“ holt sie dazu. Entfernen: Auf der Kampagnenseite unter „Listen in dieser Kampagne“ bei der Liste auf „Entfernen“ klicken – alle Empfänger aus dieser Liste kommen raus und bekommen keine weitere E-Mail (die Kontakte selbst bleiben). Einzelne Empfänger entfernst du in der Empfängertabelle mit „Entfernen“. Einzelne Kontakte hinzufügen: E-Mail-Kampagnen → Reiter „Kontakte“, oben nach Liste filtern, Kontakte anhaken, in der lila Leiste die Kampagne wählen und „Zur Kampagne hinzufügen“ klicken." },
  { id: "tracking-genau", title: "Wie genau ist das Tracking? Geöffnet, Geklickt, Personen und Mails", keys: /tracking|ge(ö|oe)ffnet|öffnungs|klickrate|geklickt.*(stimmt|genau|falsch)|zahlen.*(stimmen|falsch)|(stimmt|genau).*(zahl|öffn)|personen.*mails/i, answer: "In der Kampagnenliste zählt jede Person einmal: „Geöffnet 4“ heißt, 4 Kontakte haben mindestens eine Mail geöffnet. Darunter steht klein, wie viele Mails es waren (z. B. „5 Mails“), wenn jemand mehrere Mails der Serie geöffnet hat – diese Zahl passt zum Ordner „Gesendet“, der jede Mail einzeln zeigt. Ein Link-Klick oder eine Antwort zählt immer auch als geöffnet. Nicht gezählt werden Virenscanner, Link-Vorschauen und Aufrufe in den ersten Sekunden nach dem Versand. Grenzen gibt es trotzdem: Wer Bilder blockiert, wird erst beim Klick oder bei einer Antwort erkannt, und Apple Mail lädt Bilder teils schon beim Empfang vor. Klicks und Antworten sind deshalb die verlässlichsten Zahlen. Steht bei der Zielgruppe „x nicht mehr in der Liste“ (z. B. ein gelöschter Testkontakt), nimmt „Entfernen“ diese Empfänger samt Verlauf aus der Kampagne – dann zählen die Zahlen nur noch echte Kontakte." },
  { id: "kontakt-von-hand", title: "Kontakt von Hand in der Vertriebspipeline anlegen", keys: /kontakt (von hand|manuell|anlegen|hinzufügen)|manuell(en)? kontakt|lead (von hand|manuell|anlegen)|neuer kontakt|\+ ?kontakt|einzeln(en)? kontakt anlegen/i, answer: "In der Vertriebspipeline oben in der Leiste auf „+ Kontakt“ klicken. Pflicht sind Name oder Firma und Telefon oder E-Mail; dazu Anrede, Webseite, Adresse, Stufe, Vertriebler, Kategorie, Angebotswert, eine erste Notiz und in der Kaltakquise die Liste (Standard „Eigene Kontakte“). Gibt es die E-Mail oder Telefonnummer schon, wird kein doppelter Kontakt angelegt. Mit „Danach gleich den nächsten anlegen“ bleibt das Fenster für den nächsten offen." },
  { id: "eigene-pipeline", title: "Eigene Pipelines anlegen und Karten verschieben", keys: /neue pipeline|eigene pipeline|pipeline anlegen|pipeline (umbenennen|löschen)|in andere pipeline|karte verschieben|stufe (wählen|verschieben)|in stufe/i, answer: "Vertriebspipeline → Einstellungen → Stufen: oben bei „Reihenfolge der Pipelines“ auf „Pipeline anlegen“ klicken und einen Namen eingeben (z. B. Messe, Empfehlungen). Eine eigene Pipeline funktioniert wie die Kaltakquise: eigene Stufen (Einstellungen → Stufen), Listen hochladen (Reiter „Listen“), anrufen, „+ Kontakt“. Umbenennen oder löschen unter Einstellungen → Stufen bei „Reihenfolge der Pipelines“; beim Löschen wandern die Karten mit Liste und Verlauf in die Kaltakquise. In jeder aufgeklappten Karte gibt es oben „In Stufe verschieben …“ (Stufe direkt wählen) und „In andere Pipeline …“." },
  { id: "stufen-farbe", title: "Farbe einer Pipeline-Stufe ändern", keys: /farbe|farben|einf(ä|ae)rben|stufe.*(farbe|bunt)|spalte.*farbe/i, answer: "Jede Stufe hat eine Standardfarbe. Eigene Farbe: Vertriebspipeline → Einstellungen → Stufen: Vorne an jeder Stufe sitzt ein farbiger Punkt. Draufklicken, Farbe wählen, „Speichern“. Die Spalte, der Zähler und der Streifen an den Karten nehmen sofort die neue Farbe an. Jede Pipeline hat ihre eigenen Stufen und damit eigene Farben. „Standardfarben“ setzt eigene Farben wieder zurück. Neue Pipelines legst du nur dort an: oben bei „Reihenfolge der Pipelines“ mit „Pipeline anlegen“." },
  { id: "rueckgaengig", title: "Rückgängig machen und Papierkorb (Vertriebspipeline)", keys: /rückgängig|rueckgaengig|zurücknehmen|zurück ?setzen|papierkorb|wiederherstellen|versehentlich gelöscht|aus versehen|undo|anruf.*(löschen|entfernen)|test.*anruf/i, answer: "Fast jede Aktion in der Vertriebspipeline lässt sich zurücknehmen: Stufe, Zuteilung, Verschieben in eine andere Pipeline, Anruf-Ergebnis, Notiz, Kontakt anlegen und Löschen. Direkt danach steht in der Meldung oben rechts „Rückgängig“. Später: Reiter „Rückgängig“ in der Vertriebspipeline – dort steht alles der letzten 60 Tage mit Knopf „Rückgängig“ bzw. „Wiederherstellen“. Gelöschte Kontakte und Listen kommen mit Verlauf, Notizen, Anrufen und Kampagnen zurück. Ein einzelnes Anruf-Ergebnis (z. B. Test) löschst du auf der Lead-Seite unter „Anrufe“ mit dem ✕." },
  { id: "dubletten-upload", title: "Keine doppelten Kontakte beim Hochladen", keys: /doppelt|dublette|zweimal|mehrfach hochgeladen|nochmal hochladen|aktualisieren statt|überschreiben|gleiche liste nochmal/i, answer: "Doppelte Kontakte beim Hochladen (Einstellungen → System → „Keine doppelten Kontakte beim Hochladen“):\n• Ist der Schalter an (Standard), wird ein Kontakt, den es schon gibt, beim nächsten Hochladen nur **aktualisiert**: leere Felder werden ergänzt, Zusatzspalten dazugeschrieben, Liste und Tags angehängt. Es entsteht kein zweiter Eintrag.\n• Erkannt wird ein Kontakt an der E-Mail-Adresse oder der Telefonnummer.\n• Vorhandene Angaben werden nie überschrieben: Steht an der Karte schon eine Firma, bleibt sie stehen. Die Änderung steht im Verlauf der Karte.\n• Ist der Schalter aus, werden bekannte Kontakte beim Hochladen einfach übersprungen (wie früher).\n• Nach dem Hochladen sagt die Meldung, wie viele neu angelegt und wie viele aktualisiert wurden." },
  { id: "tags-filter", title: "Tags vergeben und danach filtern", keys: /tag|tags|schlagwort|etikett|markieren|kategorisieren|filtern nach tag|tag filter/i, answer: "Tags:\n• Beim Hochladen einer Liste gibt es das Feld „Tags“ – mehrere mit Komma trennen, z. B. „PV, Hessen“. Jeder Kontakt der Liste bekommt diese Tags, zusätzlich zum automatischen Tag „Liste: …“.\n• In den E-Mail-Kampagnen: Zielgruppe „Tag“ wählen – dann bekommen genau die Kontakte mit diesem Tag die Serie.\n• Eine Lead-Kategorie ist beim Hochladen nicht nötig; Tags reichen zum Sortieren." },
  { id: "sperrliste", title: "Sperrliste: Bounces, Abmeldungen, Posteingang sperren", keys: /sperrliste|sperren|gesperrt|entsperren|bounce|unzustellbar|abmeld|abgemeldet|unsubscribe|beschwerde|spam|protokoll|unterliste/i, answer: "Sperrliste (E-Mail-Kampagnen → „Sperrliste“):\n• Alles, was bounct, sich abmeldet oder im Posteingang gesperrt wird, landet automatisch hier – als Protokoll mit Grund, Quelle (z. B. Kampagne, Abmelde-Link, Mail-Anbieter, Posteingang) und Datum. Unterlisten: Alle, Bounces, Abmeldungen, Beschwerden, Posteingang, Manuell – mit Zählern, Suche und CSV-Export.\n• Gesperrte Adressen bekommen keine Kampagnen-E-Mails mehr (egal in welcher Zielgruppe), laufende Serien werden sofort gestoppt. „Aufheben“ gibt eine Adresse wieder frei.\n• Posteingang → „Sperren“: setzt den Absender auf die Sperrliste (Unterliste „Posteingang“) und verschiebt alle seine Nachrichten in den Filter „Gesperrt“; neue Mails von ihm landen direkt dort. „Entsperren“ macht beides rückgängig.\n• Antworten wie „bitte keine E-Mails mehr“, „unsubscribe“, „aus dem Verteiler nehmen“ erkennt der Posteingang automatisch: Adresse → Unterliste „Abmeldungen“, Serie gestoppt, Hinweis „Abmeldung erkannt“ an der Nachricht.\n• Beschwerden in Antworten („Das ist Spam“, „Hören Sie auf“, Drohung mit Anwalt/Meldung) erkennt die KI beim Aktualisieren des Posteingangs und sperrt die Adresse automatisch (Unterliste „Beschwerden“, mit Zitat und Prozentwert); ist sie sich nicht sicher, liegt die Nachricht im Posteingang unter „Prüfen“. Abschaltbar unter Einstellungen → E-Mail-Versand.\n• Bounces/Beschwerden vom Anbieter: Knopf beim Empfänger in der Kampagne oder Webhook des Mail-Anbieters (POST /api/mail/bounce, Secret MAIL_WEBHOOK_SECRET); Abmeldungen auch über den Abmelde-Link in jeder E-Mail." },
  { id: "trennung", title: "Leads zum Verkauf ≠ Vertriebskontakte", keys: /trennung|getrennt|vertriebskontakt|verkaufs-?lead|leads zum verkauf|nichts mit .* zu tun|vermischt|gemischt|unterschied.*pipeline|pipeline.*leads-seite|leads-seite.*pipeline/i, answer: "Zwei getrennte Welten:\n• Leads zum Verkauf (Lead-Operations: Leads, Bestellungen, Lieferkette, Rohdaten, Callcenter, Statistik, Dashboard) – die Anfragen, die Tanesco an Partner verkauft.\n• Vertriebskontakte (Vertriebspipeline, E-Mail-Kampagnen, Posteingang, Kaltakquise-Listen, Meta-Ads-Formulare) – Betriebe, die selbst Kunde werden sollen.\n• Beide liegen technisch getrennt (Kennzeichen „verkauf“/„vertrieb“) und tauchen nie in der jeweils anderen Ansicht auf: ein Verkaufs-Lead landet nicht in der Pipeline oder in einer E-Mail-Serie, ein Vertriebskontakt nie in Bestellungen, Lieferketten, Callcenter-Kampagnen oder Statistiken. Zielgruppen der E-Mail-Kampagnen („alle“, Liste, Stufe, Tag) bestehen nur aus Vertriebskontakten; der Posteingang verknüpft Absender nur mit Vertriebskontakten.\n• Die globale Suche zeigt beide getrennt: „Leads“ (Verkauf) und „Vertriebskontakte“ (Pipeline – öffnet direkt die Lead-Seite)." },
  { id: "email-verlauf", title: "E-Mail-Verlauf am Lead (was vorher per Mail besprochen wurde)", keys: /e-?mail-?verlauf|mailverlauf|mail-?verlauf|vorher besprochen|was besprochen|vorgeschichte|früherer schriftverkehr|schriftverkehr|konversation|unterhaltung per mail|verlauf.*mail|mail.*verlauf/i, answer: "E-Mail-Verlauf: Jeder Lead in der Vertriebspipeline zeigt alles, was mit seiner E-Mail-Adresse per Mail hin- und herging – wie ein Chat, älteste oben.\n• Was drinsteht: eingegangene Mails aus dem Posteingang (links, mit KI-Einordnung), unsere Antworten aus dem Posteingang, Einzel-E-Mails aus der Karte und der Versand aus E-Mail-Serien (rechts).\n• Vorgeschichte: Wird aus einer Nachricht im Posteingang ein Lead angelegt (oder in die Pipeline übernommen), hängen automatisch alle früheren Mails dieses Absenders und unsere Antworten darauf am Lead. Eine grüne Marke „Als Lead angelegt“ zeigt, was davor schon besprochen wurde; oben steht „n E-Mails wurden schon vor dem Anlegen ausgetauscht“.\n• Wo: In der aufgeklappten Karte die Zeile „E-Mail-Verlauf n“ (zeigt die letzten drei, „ältere anzeigen“ holt den Rest, Link zur Lead-Seite). Auf der Lead-Seite der Reiter „E-Mail-Verlauf“ mit Tagestrennern; lange Mails lassen sich mit „Ganze E-Mail“ aufklappen.\n• Antworten aus dem Posteingang werden dafür gespeichert – auch wenn es noch keinen Lead gibt; sie werden beim Anlegen nachträglich zugeordnet." },
  { id: "lead-seite", title: "Lead-Seite in der Pipeline (alles bearbeiten)", keys: /lead-?seite|lead-?fenster|leadfenster|ausführlich|alle infos|name klicken|klick auf den namen|neues fenster|bearbeiten|stammdaten|kontakt löschen|löschen|neuer tab/i, answer: "Lead-Seite (Vertriebspipeline): Klick auf den Namen einer Karte (oder der Pfeil-Knopf in der aufgeklappten Karte) wechselt auf eine eigene Seite – nur dort lassen sich alle Daten bearbeiten. Ein Klick auf die Karte selbst klappt sie dagegen breit in ihrer Spalte auf.\n• Kopf: Kategorie (Emoji + Kürzel), Quelle, Name, Firma, Ort; Stufe und Vertriebler direkt umstellbar; „Neuer Tab“ öffnet die Seite in einem eigenen Browser-Tab (nicht in der Chat-Vorschau).\n• Aktionen: Anrufen (ohne Nummer: erst eintragen), Wiedervorlage, Termin, Wert, SMS, WhatsApp, E-Mail, nächste Stufe, Verloren / Wieder aufnehmen.\n• Links: Stammdaten bearbeiten (Anrede, Vorname, Nachname, Firma, Telefon, E-Mail, PLZ, Ort, Kategorie) → „Speichern“ (jede Änderung steht im Verlauf als „Kontaktdaten“); Herkunft; Angebot & Termine; ganz unten „Kontakt löschen“ (mit Rückfrage – nur Vertriebskontakte).\n• Rechts: Verlauf, Notizen (tippen oder einsprechen), Aufgaben & Termine (erledigen), Nachrichten, Anrufe (mit Gesprächsnotiz), E-Mail-Serien, Posteingang.\n• „← Vertriebspipeline“, ✕ oder Escape führen zurück zum Board; der Link ?lead=… lässt sich teilen." },
  { id: "mikrofon", title: "Mikrofon: Notizen einsprechen", keys: /mikro|mikrofon|einsprechen|diktier|spracheingabe|sprach|aufnahme funktioniert nicht|mic\b/i, answer: "Notizen einsprechen (Lead-Seite → Notizen → Mikrofon):\n• Beim ersten Klick fragt der Browser nach der Mikrofon-Freigabe – „Zulassen“ wählen. Danach einfach sprechen; der Text erscheint live, Pausen sind egal (die Erkennung läuft weiter, bis du das Mikrofon wieder anklickst). „Speichern“ legt die Notiz mit 🎤 ab.\n• Funktioniert in Chrome, Edge und Safari (Spracherkennung des Browsers, Deutsch) – Firefox kann das nicht. Die Erkennung braucht eine Internetverbindung.\n• Freigabe verweigert? Schloss-Symbol in der Adresszeile → Mikrofon → Zulassen, dann erneut auf das Mikrofon klicken.\n• In der eingebetteten Chat-Vorschau sperrt der Browser das Mikrofon im Rahmen: dann öffnet der Mikrofon-Knopf ein kleines eigenes Fenster zum Einsprechen – dort einmal die Freigabe erteilen; der Text landet trotzdem live in der Notiz. Pop-ups für die Seite müssen erlaubt sein." },
  { id: "email-details", title: "A/B-Test, Versandfenster, Sperrliste, Vorlagen", keys: /a\/b|ab-test|betreff b|variante|versandfenster|zeitzone|werktags|bounce|unzustellbar|beschwerde|spam|sperrliste|gesperrt|vorlage|vorlagen|duplizieren|kopie|link.*geklickt|bestimmter link/i, answer: "E-Mail-Kampagnen – Details:\n• A/B-Betreff: im Ablauf bei einer E-Mail „Betreff B“ ausfüllen; Anteil B per Regler (10–90 %). Empfänger werden aufgeteilt, die Auswertung zeigt Öffnungs- und Klickrate je Variante und den Gewinner.\n• Versandfenster: nur an gewählten Wochentagen zwischen von/bis in einer Zeitzone senden – fällige Mails warten bis zum nächsten Fenster.\n• Wenn-Abfrage „Link geklickt“ kann auf einen bestimmten Link eingeschränkt werden (z. B. /termin).\n• Sperrliste (eigener Reiter „Sperrliste“): siehe Thema „Sperrliste“ – Unterlisten Bounces, Abmeldungen, Beschwerden, Posteingang, Manuell mit Grund, Quelle und Datum.\n• Vorlagen: Kampagne mit „Als Vorlage anlegen“ ablegen; die Vorlagen öffnen sich über den Knopf „Vorlagen“ in der Kopfzeile der Kampagnen (kein eigener Reiter), dort „Kampagne daraus anlegen“; „Kopie“ dupliziert eine Kampagne ohne Empfänger. „Neue Kampagne“ bietet Kaltakquise, Nachfassen nach Angebot und Aufwecken." },
  { id: "email-kampagnen", title: "E-Mail-Kampagnen & Kaltakquise", keys: /e-mail-kampagne|email-kampagne|kaltakquise|liste hochladen|listen hochladen|e-?mail-?liste|excel|xlsx|hochladen|anrufkampagne|power|predictive|newsletter|serie|nachfassen|builder|geöffnet|geklickt|posteingang|antwort|imap/i, answer: "Kaltakquise & E-Mail-Kampagnen (Menü Vertrieb):\n• Listen hochladen: Vertriebspipeline → oben „Kaltakquise“ → Reiter „Listen & Kontakte“ → Excel- oder CSV-Datei auswählen oder hineinziehen (Kopfzeile mit Vorname, Nachname, Firma, Telefon, E-Mail, PLZ, Ort; erstes Tabellenblatt). Name der Liste und Zuteilung (Taner/Francesco 50/50, nur einer, später) wählen → „In die Pipeline übernehmen“. Kontakte landen in der Pipeline unter „Neu“; Dubletten werden übersprungen. Für eine E-Mail-Serie zu dieser Liste: E-Mail-Kampagnen → Neue Kampagne → Zielgruppe „Liste“ → Liste wählen (nur Kontakte mit E-Mail-Adresse, Sperrliste wird abgezogen). Kürzer: Direkt im Kampagnen-Editor unter Zielgruppe „Liste“ steht „Neue Liste hochladen“ – Excel/CSV hineinziehen oder „Datei wählen“, Name prüfen, „Hochladen und als Zielgruppe wählen“ – die Liste ist sofort als Zielgruppe gesetzt (Kontakte landen gleichzeitig in der Kaltakquise-Pipeline).\n• Spalten zuordnen: Nach dem Auswählen der Datei zeigt „Spalten zuordnen“ jede Spalte mit Beispielwert und einer Auswahl: Standardfeld (Anrede, Vorname, Nachname, Firma, Telefon, E-Mail, PLZ, Ort, Notizen), „Platzhalter {{spaltenname}}“ oder „nicht übernehmen“. Bekannte Überschriften werden automatisch erkannt, unbekannte Spalten (z. B. Branche, Anzahl Mitarbeiter) werden automatisch zu Platzhaltern. Jede Änderung wertet die Datei sofort neu aus.\n• Platzhalter aus der Liste: Zusatzspalten stehen als {{branche}}, {{anzahl_mitarbeiter}} usw. zur Verfügung (Umlaute werden umgeschrieben, Leerzeichen zu _). Im Builder zeigt die Leiste „Platzhalter einfügen“ alle festen Platzhalter ({{anrede}}, {{vorname}}, {{nachname}}, {{name}}, {{firma}}, {{stadt}}, {{email}}, {{abmelden}}) und grün die aus der gewählten Liste – ein Klick fügt sie in das zuletzt benutzte Textfeld ein (Betreff, Vorschautext, Baustein). Die Vorschau zeigt Beispielwerte aus der Liste. Beim Versand werden sie je Empfänger gefüllt – auch in Einzel-E-Mails, SMS und WhatsApp aus der Karte. Die Felder stehen außerdem auf der Lead-Seite unter „Aus der Liste“ und in der aufgeklappten Karte. Dann „Anrufen“ im Modus Manuell, Power oder Predictive – die Anrufkampagne läuft unter „Telefonie“ wie im Callcenter.\n• Versandfenster: Jede neue Kampagne sendet standardmäßig nur werktags zu Arbeitszeiten, 7:30–17:00 Uhr (Berlin) – **freitags nur bis 13:00 Uhr**; fällige E-Mails außerhalb warten bis zum nächsten Fenster. Im Editor unter „Versandfenster“ lassen sich Tage, Uhrzeiten und Zeitzone ändern. Darunter steht „Abweichende Zeiten je Tag“: dort bekommt jeder Wochentag eigene Uhrzeiten (z. B. Freitag 7:30–13:00), „zurücksetzen“ nimmt die Ausnahme wieder weg. „Auf Standard zurücksetzen“ stellt alles wieder her, das Häkchen aus = rund um die Uhr.\n• E-Mail-Kampagnen: „Neue Kampagne“ bringt eine fertige Serie mit: 1. E-Mail → 72 Stunden warten → Wenn geöffnet → Dann Nachfass-E-Mail A, Sonst Nachfass-E-Mail B. Oben fasst „So läuft es“ den ganzen Ablauf in einer Zeile zusammen. Die Schritte hängen an einer Linie; das „+“ auf der Linie klappt die Auswahl auf (E-Mail, Warten, Wenn … dann, Ende). „Warten“ hat Schnellwahl (1 Tag, 2 Tage, 3 Tage, 1 Woche). „Wenn … dann“ steht als Satz („Wenn der Empfänger … geöffnet hat / einen Link geklickt hat / geantwortet hat“), darunter zwei Zweige: links „Dann“ (trifft zu), rechts „Sonst“ – jeder Zweig zeigt im Kopf kurz, was darin passiert (z. B. „1 E-Mail → Ende“). Jede E-Mail im Ablauf zeigt eine echte Vorschau (die fertige Mail, verkleinert), in schmalen Zweigen kompakt – Klick auf die Vorschau öffnet den Builder.\n• Builder: Bausteine (Überschrift, Text, Aufzählung, Bild, Knopf, Linie, Signatur) plus Design (Farben, Schrift, Logo, Fußzeile) mit Live-Vorschau und Testmail.\n• Kopieren: Im Ablauf hat jede E-Mail und jede Wartezeit ein Kopier-Symbol neben dem Papierkorb – die Kopie hängt sofort dahinter, bei einer E-Mail mit allen Bausteinen. Im Builder hat jeder Baustein ebenfalls ein Kopier-Symbol neben den Pfeilen; die Kopie erscheint direkt darunter. Eine Verzweigung lässt sich nicht kopieren, weil zwei ganze Zweige daran hängen.\n• Verschieben: Neben dem Kopier-Symbol steht die Auswahl „Verschieben …“. Sie bietet jede Stelle im Ablauf an: ganz an den Anfang, hinter einen bestimmten Schritt oder in den Dann- bzw. Sonst-Zweig einer Verzweigung. Der Rest des Ablaufs bleibt verbunden – der Vorgänger zeigt danach auf den Nachfolger.\n• Links in der Fußzeile: Im Design unter „Fußzeile“ stehen Knöpfe für Webseite, Terminlink und E-Mail. Eigener Text geht so: [Termin vereinbaren](https://cal.com/tanesco) – vorn der sichtbare Text, hinten die Adresse. Eine blanke Adresse wie tanescodigital.de wird von selbst anklickbar. Anschrift, Webseite und Terminlink stehen unter Einstellungen → Branding; neue Kampagnen übernehmen sie von selbst, für bestehende gibt es dort den Knopf „Auf bestehende Kampagnen übernehmen“. Bausteine verschieben: am Griff links ziehen und an jeder Stelle ablegen (auch ganz nach oben), oder mit den Pfeilen bzw. „Ganz nach oben“; der verschobene Baustein leuchtet kurz auf. Platzhalter wie {{vorname}} oder {{firma}}.\n• Drei Pipelines unter Vertriebspipeline: Meta Ads, Kaltakquise und E-Mail-Kampagne (Empfänger der Serien; Antworten setzen den Lead automatisch auf „Kontaktiert“).\n• Posteingang (Reiter in E-Mail-Kampagnen): holt Antworten per IMAP ab (Einstellungen → E-Mail-Versand → Antworten erkennen), zeigt Antworten auf Serien, unbekannte Anfragen und Ungelesenes; Absender mit „Als Lead in Pipeline“ in die Meta-Ads- oder Kaltakquise-Pipeline übernehmen (Stufe, Vertriebler), direkt antworten, archivieren.\n• Zielgruppe: Alle Kontakte mit E-Mail, eine Liste, eine Pipeline-Stufe oder ein Tag. Nach „Starten“ laufen die Schritte automatisch (Zeitplaner); Öffnungen und Klicks werden über Pixel/Links gemessen, „Fällige Schritte jetzt ausführen“ stößt sofort an. Echter Versand braucht SMTP_URL/SMTP_FROM." },
  { id: "benutzer", title: "Benutzer & Kundenbereich", keys: /benutzer|nutzer|käufer|kunde|lieferant|team|rolle|als benutzer einloggen|ansicht|freigabe/i, answer: "Benutzer: „Neuer Benutzer“ (Käufer, Lieferant, Admin, Vertriebler) mit Passwort. Auf der Detailseite: Reiter „Ansicht“ (welche Menüpunkte der Kunde sieht), „Integration“ (Endpunkt, Vorlagen, Preset), „Reklamation“ (Frist, Token), „Lieferant“ (Token, Rückgabe-Webhook), „Aktivität“. „Als Benutzer einloggen“ zeigt dir seinen Kundenbereich (gelbes Banner, „Zurück zum Admin“). Teams gruppieren Benutzer, Kooperationen sind externe Partner." },
  { id: "tags", title: "Tags", keys: /\btags\b|lead-tag|tag setzen|tags-seite|marker|label/i, answer: "Tags sind farbige Marker für Leads: unter „Tags“ anlegen/umfärben/umbenennen; am Lead (Quick View) per Klick setzen; im Filter und in Automatisierungen („Lead-Tag setzen“) nutzbar. Die Tags-Seite zeigt Nutzung, letzte Verwendung und Beispiel-Leads." },
  { id: "darstellung", title: "Darstellung (Hell/Dunkel)", keys: /hell|dunkel|dark|light|darstellung|design|farbe|automatisch|sonne|system|modus/i, answer: "Darstellung: Sonne/Mond-Symbol oben rechts (oder Einstellungen → Profil) → Hell, Dunkel, Automatisch (hell am Tag, dunkel nach Sonnenuntergang – Standort einmal freigeben) oder Wie System (folgt deinem Gerät). Die Wahl bleibt im Browser gespeichert. Logo und Primärfarbe stellst du unter Einstellungen → Branding ein." },
  { id: "live-bild", title: "Live-Bild: viele Agenten im Blick, Reinhören", keys: /live-?bild|wer spricht gerade|agenten im blick|teamleiter|supervisor|reinhören|mithören|mithoeren|agent pausieren|agenten steuern/i, answer: "Live-Bild (Telefonie → Live-Bild):\n• Oben die Tageszahlen: angemeldete Agenten, wer gerade spricht, Anrufe heute, erreicht, Termine/Verkäufe, Gesprächszeit.\n• Je Agent eine Karte: Status (bereit, wählt, im Gespräch, Nachbereitung, Pause), seit wann, laufendes Gespräch mit Name, Nummer, Dauer und ob die Aufzeichnung läuft; darunter die Tageszahlen des Agenten (Anrufe, erreicht, Termine, Gesprächszeit, Ø Bewertung). Aktualisiert sich alle 3 Sekunden.\n• Steuern: Pause / wieder bereit, Kampagne wechseln, abmelden – nicht während eines Gesprächs.\n• Kampagnen im Lauf mit Fortschrittsbalken (offen, gerade, erledigt) und Anzahl der Agenten darauf.\n• **Reinhören**: Sobald ein Gespräch zu Ende ist, steht es unten mit Ergebnis, Bewertung und Notiz – „Reinhören“ spielt die Aufzeichnung direkt ab. Live in ein laufendes Gespräch hineinhören geht nur in der sipgate-App (Paket „Contact Center“) – das Live-Bild zeigt dir, wen du dort anhören willst." },
  { id: "sipgate", title: "Telefonie über sipgate", keys: /sipgate|zipgate|sip-?gate|personal access token|token-id|click-?to-?dial|sipgate-app|tischtelefon|anbieter wechseln|telefonanbieter/i, answer: "sipgate als Telefonanbieter (Telefonie → Einstellungen → Modus „sipgate“):\n• **Token**: In der sipgate-Web-App unter Konto → „Personal Access Tokens“ einen Token anlegen – mit Rechten für Anrufe (sessions:calls / rtcm), Geräte, Rufnummern, SMS, Verlauf (history) und sipgate.io-Einstellungen. Token-ID und Token in der Software eintragen → „Speichern & Verbindung prüfen“. Die Software erkennt, ob es sipgate classic (team/trunking) oder sipgate neo ist, und zeigt Geräte und Rufnummern.\n• **Rufnummern**: kaufst du bei sipgate; „Rufnummern aus sipgate übernehmen“ holt sie in die Software (Absender für Anrufe und SMS). Ein Kauf in der Software gibt es bei sipgate nicht.\n• **So läuft ein Anruf**: Die Software sagt sipgate „ruf von Gerät e0 die Nummer an“ – zuerst klingelt dein sipgate-Gerät (sipgate-App am Rechner/Handy, Tischtelefon oder dein Handy als externes Gerät), nach dem Abheben wird der Kunde gerufen. Kein Browser-Softphone, kein Headset im Browser nötig. Beim Start der Dialer-Sitzung wählst du dein Gerät; ein Standard-Gerät steht in den Einstellungen.\n• **Modi**: Manuell und Power-Dialer (Liste nacheinander) gehen. Predictive (mehrere Nummern gleichzeitig) kann sipgate nicht.\n• **Status live**: „Webhook bei sipgate eintragen“ trägt die Adresse der Software bei sipgate ein (sipgate.io / Push-API) – dann meldet sipgate klingelt/abgenommen/aufgelegt sofort. Ohne Webhook sieht die Software alle paar Sekunden in der Liste der aktiven Anrufe nach (dann gilt „in der Liste“ als verbunden).\n• **Aufzeichnung**: startet über die sipgate-API – mit sipgates eigener Ansage (Einstellung „Ansage“), per Klick des Agenten oder ohne Abfrage. Die fertige Datei holt sich die Software kurz nach dem Gespräch aus dem sipgate-Verlauf und bewertet sie wie gewohnt.\n• **SMS** gehen über sipgate (SMS-Kennung meist „s0“); WhatsApp nicht.\n• Die Software muss für Webhooks öffentlich über https erreichbar sein (bei Railway der Fall)." },
  { id: "pipeline-dialer", title: "Dialer in der Vertriebspipeline", keys: /pipeline.*(anruf|dialer|wählen|waehlen|telefon)|(anruf|dialer|wählen|waehlen).*pipeline|karte anrufen|stufe abtelefonieren|abtelefonieren|direkt anrufen/i, answer: "Dialer in der Vertriebspipeline:\n• Karte öffnen → „Anrufen“: der Anruf läuft unten im Dialer-Feld (Klingelt → Verbunden → Auflegen), ohne die Pipeline zu verlassen. Telefon-Symbol im Spaltenkopf = ganze Stufe als Wählliste: Manuell (du startest jeden Anruf), Power (nach jedem Ergebnis sofort der nächste) oder Predictive (mehrere Nummern gleichzeitig, angenommene Gespräche werden durchgestellt). Die Liste wird als Kampagne „Pipeline: …“ angelegt; Besetzt/Keine Antwort/Anrufbeantworter werden als „Nicht erreicht“ verbucht und nach 4 Stunden erneut versucht (höchstens 3-mal).\n• Nach dem Gespräch: Ergebnis wählen (Verkauft/Termin, Interessiert, Wiedervorlage, Nicht erreicht, Kein Interesse, Falsche Nummer, Nicht mehr anrufen) – die Karte rückt passend vor (Verkauft → Termin, Interessiert → Qualifiziert, Wiedervorlage → Kontaktiert, Kein Interesse → Verloren; nie zurück).\n• Automatische Gesprächsnotiz: Schalter „Auto-Notiz“ oben im Dialer; die Notiz erscheint an der Karte, im Verlauf und unter Telefonie → Anrufe.\n• Voraussetzung: eine Rufnummer (Telefonie → Rufnummern); bei sipgate klingelt zuerst das sipgate-Gerät des Agenten (App, Tischtelefon, Handy), in der Simulation läuft alles ohne Audio." },
  { id: "wattfox-auslieferung", title: "Leads an Wattfox ausliefern (Vorlage Wattfox, Testleads)", keys: /wattfox|testlead|photovoltaik angebotsvergleich|productid|childinterests|otherinterests|zusatzinteresse|utm_source|utm_medium/i, answer: "Leads an Wattfox:\n• Benutzer → Wattfox → Reiter „Integration“ → bei Photovoltaik, bei Wärmepumpe und – wenn es die Kategorie gibt – bei Photovoltaik & Wärmepumpe je „Endpoint hinzufügen“ → im Bereich Body „Vorlage Wattfox“ → unter „Zugangsdaten“ neben „user“ den Benutzernamen und neben „pass“ das Passwort von Wattfox eintippen → Speichern.\n• Zugangsdaten immer selbst eintippen: Der Browser setzt dort nichts ein; mit dem Auge siehst du, was du eintippst. Gespeichert: Benutzername lesbar, das Passwort steht als „gespeichert“ – zum Prüfen neu eintippen. Steht dort dein Passwort für diese Software, speichert und sendet die Software nicht.\n• Die Felder baut die Software selbst: Photovoltaik = Produkt 2, Wärmepumpe = Heizung (20) mit dem Zusatz Wärmepumpe (6). Will jemand beides („Wärmepumpe: Ja“ bzw. „Interesse Photovoltaikanlage: Ja“), geht EIN Lead mit Zusatzinteresse raus. Unsere Angaben werden in die Werte von Wattfox übersetzt (z. B. „1-3 Monate“ → „1 bis 3 Monate“, Stromverbrauch als Zahl: „4.000 - 6.000 kWh“ → 5000); was nur ungefähr passt, steht zusätzlich im Hinweisfeld.\n• Im Body stehen nur die Herkunftsangaben: utm_source „Tanesco Digital GbR“ und utm_medium „affiliate“ nie ändern; utm_campaign „Hauskompass, Meta vorqualifiziert“ zeigt den Callagents von Wattfox, unter welcher Marke der Kunde gewonnen wurde – nur nach Rücksprache mit Wattfox ändern (leer geht das Feld nicht mit).\n• Fehlt eine Pflichtangabe (Anrede bei PV, Vor- und Nachname, Straße, PLZ, Ort, Telefon, E-Mail), geht der Lead nicht raus und steht unter „API-Fehler“ – korrigieren und noch einmal ausliefern.\n• Testphase: „Testleads an Wattfox senden (3)“ schickt je einen Testlead für Photovoltaik, für Wärmepumpe und einen mit beidem (erfundene Daten) an die Testumgebung und zeigt die Nummern von Wattfox – mit „Nummern kopieren“ für die Mail an Wattfox. Will Wattfox je 3, gibt es daneben „Alle 9“.\n• Live (Wattfox hat am 25.11. freigegeben): bei jedem Wattfox-Endpoint (Photovoltaik, Wärmepumpe, Photovoltaik & Wärmepumpe) „Live-Adresse einsetzen“ (Benutzername und Passwort bleiben dabei stehen) → steht dort noch der Test-Zugang, Benutzername und Passwort des Live-Zugangs eintippen → Speichern → wieder öffnen → unten rechts „Anmeldung prüfen“. Den Knopf gibt es erst, wenn die Live-Adresse gespeichert ist. Das prüft nur Adresse und Zugang – es geht kein Lead raus (Testleads gibt es nur für die Testumgebung). Dann die Bestellung Wattfox aktivieren, einen echten Lead mit „Jetzt ausliefern“ testen (die Wattfox-Nummer steht im Lead-Log) und unter Gespräche → „Dialer & Bewertung“ → „Anbindung“ auf „Sofort ausliefern“ stellen. Die bisherige Lieferung abschalten, damit nichts doppelt ankommt.\n• Freitext (notes): Erreichbarkeit und genaue Werte „laut Gespräch“ stehen dort zur Info – Wattfox wertet sie nicht automatisch aus (Antwort vom 25.11.).\n• Die Lead-Nummer von Wattfox („wf_leadid“) steht danach am Lead." },
  { id: "kampagnen-vom-dialer", title: "Kampagnen vom Dialer trennen – Regeln und Käufer je Kampagne", keys: /kampagnen? (vom|aus dem|im) dialer|dialer-?kampagne|kampagne laut dialer|im dialer:|zuordn.*kampagne|kampagne.*zuordn|leads gehen an|k(ä|ae)ufer (der|dieser|je) kampagne|nur an (wattfox|aroundhome)|aroundhome-?leads|kampagnen trennen|nach kampagne/i, answer: "Kampagnen vom Dialer:\n• Der Dialer schickt je Gespräch den Namen seiner Kampagne mit (Feld „campaign“). Am Gespräch steht er unter „Kampagne“ als „im Dialer: …“, wenn er anders heißt als die Kampagne hier.\n• Gespräche → Einstellen → „Kampagnen vom Dialer“: je Name aus dem Dialer, wie viele Gespräche kamen und wo sie landen. Im Auswahlfeld eine Kampagne wählen (oder „Neue Kampagne …“) → die bisherigen Gespräche kommen mit, neue landen direkt dort, mit den Prüffragen und Kriterien dieser Kampagne. Fehlende Prüffragen holt die Software nach – Entscheidungen werden dabei nur strenger. Hat die Nachprüfung ein Gespräch wegen einer Frage strenger entschieden, die es in der neuen Kampagne nicht gibt, wird das zurückgenommen.\n• „Neue Kampagne …“ übernimmt die Prüffragen und Kriterien der Kampagne, in der die Gespräche bisher lagen – die Bewertung bleibt also gleich. Den Käufer übernimmt sie nicht; den wählst du selbst.\n• Ohne Zuordnung landen Gespräche in der Kampagne mit gleichem Namen, sonst in „Neue Gespräche vom Dialer landen in“.\n• Käufer je Kampagne: Kampagne wählen → „Leads aus dieser Kampagne gehen an“ → Käufer wählen. Dann bekommt nur er die Leads aus dieser Kampagne – andere Käufer nicht, auch wenn ihre Bestellung oder Lieferkette passt (im Verlauf des Leads steht „Kampagne … liefert nur an …“). Steht der Käufer in keiner passenden Lieferkette oder Bestellung, bleibt der Lead liegen und der Grund steht dabei.\n• Umgekehrt: Ein Käufer, der fest zu einer Kampagne gehört, bekommt keine Leads aus anderen Kampagnen („… bekommt nur Leads aus „…““). Leads ohne Gespräch (z. B. von Lieferanten) betrifft das nicht.\n• „alle passenden Käufer“: Bestellungen und Lieferketten entscheiden – außer bei Käufern, die fest zu einer anderen Kampagne gehören." },
  { id: "pruefragen-nachholen", title: "Neue Prüffrage – gilt sie auch für ältere Gespräche?", keys: /(neue|ge(ä|ae)nderte) pr(ü|ue)ffrage|(ä|ae)ltere gespr(ä|ae)ch|nachpr(ü|ue)f|nachgepr(ü|ue)ft|nachholen.*(frage|gespr)|bis zu (3|drei) angebote|fachpartner/i, answer: "Prüffragen bei älteren Gesprächen:\n• Kommt eine Prüffrage dazu (z. B. „Wurde am Ende gesagt, dass der Kunde bis zu 3 Angebote von Fachpartnern bekommt?“) oder bekommt eine Kampagne andere Fragen, holt die Software die Antwort bei allen älteren Gesprächen nach – ein paar pro Minute, nur die fehlende Frage (kostet wenig).\n• Über der Liste der Gespräche steht, wie viele noch warten und welche Frage nachgeholt wird.\n• Die Entscheidung wird dabei nur strenger, nie lockerer: Fehlt eine Pflicht-Antwort, wird das Gespräch zurückgewiesen und sein Lead auf „Fehlerhaft“ gesetzt; ist eine Antwort unklar, geht das Gespräch zur Prüfung und der Lead auf „Hängend“. Schon ausgelieferte Leads bleiben, wie sie sind – im Verlauf steht ein Vermerk.\n• Von Hand entschiedene Gespräche bekommen die Antwort, behalten aber ihre Entscheidung.\n• „Diese Gespräche zeigen“ filtert die Liste auf die geänderten; sie tragen den Hinweis „nachgeprüft“. Wer ein Gespräch anhört und doch freigibt, entscheidet von Hand – das gilt.\n• Ist die Tagesgrenze der KI für Gespräche erreicht, ruht die Nachprüfung bis wieder Budget frei ist." },
  { id: "ki-kosten-gespraeche", title: "Was kostet die KI bei den Gesprächen – und wo steht der Verbrauch?", keys: /ki-?(kosten|verbrauch|budget|grenze|obergrenze)|was kostet.*(ki|gespr|bewert|anh(ö|oe)r)|kosten.*(gespr|bewertung|abschrift|transkri)|api-?verbrauch|obergrenze|tagesgrenze|whisper|mitschreiben/i, answer: "KI bei Gesprächen:\n• Es sind zwei Posten: Mitschreiben der Aufnahme (Abschrift, etwa 0,55 Cent je Minute) und Bewerten (Punkte, Prüffragen, Agent, Kontakt – etwa 2 bis 3 Cent je Gespräch). Faustregel: rund 1 Cent je Gesprächsminute.\n• Wo es steht: Gespräche → Knopf „KI heute“ (neben „Einstellen“). Das Fenster „KI-Verbrauch“ zeigt je Tag, was wofür gekostet hat – mit eigener Zeile für die Gespräche: Mitschreiben, Bewerten, Preis je Gespräch.\n• Obergrenze je Tag: im Fenster „Obergrenze ändern“ (0 = keine Grenze). Ist sie erreicht, werden neue Gespräche angenommen, warten aber mit dem Vermerk „Tagesgrenze der KI erreicht“ und werden später von selbst bewertet – am nächsten Tag oder sobald die Grenze höher ist. Es geht kein Gespräch verloren. „Neu bewerten“ von Hand geht immer.\n• Die Beträge sind ungefähr. Die genaue Rechnung steht beim Anbieter: Bewertung bei Anthropic (platform.claude.com/usage), Abschrift bei OpenAI (platform.openai.com/usage)." },
  { id: "gespraechsnotiz", title: "Automatische Gesprächsnotiz", keys: /gesprächsnotiz|gespraechsnotiz|automatische notiz|auto-notiz|zusammenfassung|notiz.*anruf|anruf.*notiz|transkript|mikrofon|spracheingabe|einsprechen/i, answer: "Automatische Gesprächsnotiz (alle Dialer):\n• Nach jedem Gespräch entsteht eine Notiz am Kontakt – Zusammenfassung, wichtige Punkte, nächster Schritt, Ergebnis und Dauer. Mit KI-Schlüssel (ANTHROPIC_API_KEY) fasst die KI das Transkript zusammen, sonst gibt es eine Kurzfassung; ohne Aufzeichnung/Einwilligung besteht die Notiz aus Ergebnis, Dauer und Agenten-Notiz.\n• Ein/Aus: Schalter „Auto-Notiz“ direkt im Dialer (Telefonie → Wählen und im Pipeline-Dialer), bei der Anrufkampagne in der Kaltakquise, je Kampagne (Telefonie → Kampagnen) und als Standard unter Telefonie → Einstellungen.\n• Die Notiz steht an der Pipeline-Karte (blau, „automatisch aus dem Gespräch“), im Verlauf des Leads und unter Telefonie → Anrufe (Spalte Notiz).\n• Spracheingabe für eigene Notizen braucht Mikrofonzugriff: In der eingebetteten Chat-Vorschau sperrt der Browser das Mikrofon; in der installierten Version (https) fragt er einmal nach der Freigabe." },
  { id: "aufzeichnung", title: "Aufzeichnung & Einwilligung", keys: /aufzeichn|aufnahme|einwilligung|ansage|201 stgb|ohne abfrage|recording/i, answer: "Aufzeichnung (Telefonie → Einstellungen → Aufzeichnung & Einwilligung):\n• Standard: Ansage zu Gesprächsbeginn oder Klick des Agenten „Einwilligung erteilt“ – erst dann wird aufgezeichnet und bewertet.\n• Schalter „Ohne Einwilligungsabfrage aufzeichnen“: Aufzeichnung ab Gesprächsbeginn ohne Ansage und ohne Klick – nur wenn die Einwilligung bereits anders vorliegt (z. B. im Lead-Formular bestätigt). Wichtig: In DE/AT/CH ist das Aufzeichnen ohne Einwilligung aller Beteiligten strafbar (§ 201 StGB); die Software dokumentiert solche Aufzeichnungen als „ohne Abfrage“.\n• „Gespräche aufzeichnen und bewerten“ aus = keine Aufzeichnung, Gesprächsnotizen dann nur aus den Anrufdaten." },
  { id: "callcenter", title: "Callcenter", keys: /rohdaten|telefon|anruf|dialer|gespräch|kampagne|bewertung|live-bild|agenten live|wer spricht gerade|reinhören|mithören/i, answer: "Callcenter: „Rohdaten“ = Listen mit Kontakten, die noch keine Leads sind. „Liste hochladen“ nimmt CSV oder Excel (Datei ins Feld ziehen oder klicken), erkennt die Spalten und sagt vor dem Hochladen, wie viele Kontakte es werden. Jede Liste ist eine Karte mit Balken: Leads, in Wählliste, neu, verworfen, doppelt. „Ins Callcenter“ legt daraus eine Wählliste an; „Kontakte zeigen“ grenzt Auswertung und Kontakte auf diese Liste ein. Bei den Kontakten gibt es Reiter nach Status und eine Suche; offene Kontakte kannst du von Hand zum Lead machen oder verwerfen. „Telefonie“ = Kampagnen, Anrufe (sipgate-Zugang unter Telefonie → Einstellungen), Gesprächsergebnis setzen. „Gespräche“ = Aufzeichnungen/Transkripte mit KI-Bewertung nach Kriterien." },
  { id: "dialer-webhook", title: "Fremder Dialer (OnDialer) anbinden: Webhook „Gespräch beendet“", keys: /ondialer|dialer.*(anbind|webhook|schnittstelle|doku|entwickler)|webhook.*(gespräch|dialer)|aufnahme.*(nicht fertig|später)|testmodus|prüf-?adresse/i, answer: "Fremden Dialer anbinden (Callcenter → Gespräche → „Dialer-Anbindung“):\n• Adresse kopieren und im Dialer als Webhook für „Gespräch beendet“ hinterlegen – der Dialer schickt je Gespräch Gesprächs-ID, Rufnummer, Agent, Kampagne, Dauer, Zeitpunkt und den Link zur Aufnahme (JSON). Pflicht: call_id, phone, recording_url; mit „Einwilligung erforderlich“ zusätzlich consent: true.\n• „Anleitung für den Dialer-Entwickler kopieren“: fertige Beschreibung mit Adresse, Feldnamen, Beispiel, Antworten und Testmodus – ohne Produktname, zum Einfügen in eine E-Mail.\n• Prüfen: Aufruf der Adresse im Browser (GET) zeigt, ob Adresse und Schlüssel stimmen; ein Testgespräch mit \"test\": true prüft Felder und Aufnahme-Link, ohne etwas zu speichern.\n• Aufnahme noch nicht fertig? Wir holen sie automatisch nach – bis zu 8 Versuche über ca. 4 Stunden (2, 4, 8 … 60 Minuten). Dieselbe Gesprächs-ID wird nie doppelt ausgewertet.\n• Zuordnung: erst nach Lead-ID, dann nach Rufnummer zu einem Lead; gibt es keinen, zu einem Kontakt aus einer Rohdaten-Liste – wird das Gespräch freigegeben, wird er automatisch zum Lead, bei Ablehnung verworfen.\n• Felder heißen beim Dialer anders? Unter „Felder des Dialers zuordnen“ eintragen (auch verschachtelt, z. B. call.id). Aufnahme-Links mit Schlüssel: „Zugriffs-Header“ eintragen.\n• Transkription braucht einen OpenAI- oder Deepgram-Schlüssel auf dem Server – oder der Dialer schickt das Transkript mit." },
  { id: "zurueck-einstellungen", title: "Einstellungen: Zurück und Bereich wechseln", keys: /zurück.*einstellung|einstellung.*zurück|nicht zurück|komme nicht (mehr )?raus|bereich wechseln|brotkrumen|zurück-?knopf|zurueck/i, answer: "In den Einstellungen steht über jedem geöffneten Bereich eine Leiste: „← Zurück zu den Einstellungen“ bringt dich zur Liste, daneben siehst du, wo du bist (Einstellungen › Bereich), und rechts kannst du mit „Bereich wechseln“ direkt in einen anderen Bereich springen – auch aus den breiten Bereichen wie Integrationen oder API-Dokumentation. Der Zurück-Pfeil des Browsers funktioniert ebenfalls." },
  { id: "laptop", title: "14-Zoll-Laptop: alles im Bild", keys: /laptop|14[ -]?zoll|kleiner bildschirm|klein(er|es) (fenster|display)|hin und her scrollen|querscroll|eingeklappt|seitenleiste (weg|eingeklappt|ausklappen)|spalte (ein|aus)klappen|kunde.*verloren.*schmal/i, answer: "Auf Laptop-Bildschirmen (bis 1480 px breit) startet die Seitenleiste eingeklappt – mit dem Pfeil oben links klappst du sie wieder aus, die Wahl wird gemerkt. Die Vertriebspipeline füllt dann den Bildschirm: Die Spalten scrollen innen, „Kunde“ und „Verloren“ stehen als schmale Streifen mit Zahl rechts (Klick klappt sie aus; jede Spalte lässt sich über den Doppelpfeil im Spaltenkopf einklappen – Karten kannst du trotzdem darauf ziehen). In den E-Mail-Kampagnen bleibt „Bearbeiten“ rechts immer erreichbar, bei den Kontakten bleibt der Name beim Schieben stehen, und im Builder bleibt die Vorschau neben den Bausteinen stehen." },
  { id: "agenten-auswertung", title: "Gespräche: Auswertung je Agent", keys: /agenten?-?auswertung|wer (macht|telefoniert) (was|wie viel)|welcher agent|agenten vergleichen|bestenliste|rangliste|agenten bewerten|bewertung (der|je) agent|erreicht-?quote|erfolgsquote|agent(en)? (löschen|entfernen|zurückholen)|gelöschte agenten|weitere zeiträume|zeitraum.*(gespräche|agenten|bestenliste)|(gespräche|agenten|bestenliste).*zeitraum/i, answer: "Unter Gespräche → „Agenten“ siehst du je Agent: Anrufe, wie viele erreicht wurden (Quote), Gesprächszeit, Termine, Interessiert, Wiedervorlagen, kein Interesse, die Ø Punkte der KI-Bewertung und wie viele Gespräche freigegeben, zur Prüfung oder zurückgewiesen wurden. „Gespräche“ an einer Zeile öffnet die Anrufe dieses Agenten – mit demselben Zeitraum und derselben Kampagne.\n• Zeitraum (Bestenliste und Gesprächsliste gleich, seit Version 378): schnelle Knöpfe Heute, Gestern, 7 Tage, 30 Tage, Gesamt. Daneben „Weitere Zeiträume“ wie auf der Leads-Seite: Diese Woche, Letzte Woche, Letzte 2 Wochen, Dieser Monat, Letzter Monat – und eigene: Zwischen … (beide Tage zählen mit), Ab …, Vor … (der gewählte Tag zählt nicht mehr mit). Verglichen wird mit dem Abschnitt davor: Woche gegen Woche, Monat gegen Monat, sonst genauso viele Tage davor.\n• Agenten löschen (seit Version 378): Der Papierkorb am Ende einer Zeile nimmt den Agenten aus der Bestenliste – aus Plätzen, Summen, Bestwerten und „Zuletzt erreicht“. Seine Gespräche bleiben in der Liste „Gespräche“. Gelöscht bleibt gelöscht: Neue Gespräche unter dem Namen zählen erst wieder mit, wenn du ihn zurückholst. Unter der Rangliste steht „Gelöschte Agenten“ mit dem Knopf „Zurückholen“. Das dürfen Inhaber, Admin und Manager." },
  { id: "rohdaten-kategorien", title: "Rohdaten: Was wurde aus den Kontakten – je Kategorie", keys: /was wurde (daraus|aus)|je kategorie|pro kategorie|wie viele leads (von|je|pro) (welcher )?kategorie|rohdaten.*(kategorie|auswertung|ergebnis)|kategorie.*rohdaten|verlauf(s)?-?balken/i, answer: "Unter Rohdaten steht zwischen den Listen und den Kontakten die Tabelle „Was wurde aus den Kontakten?“: je Kategorie, wie viele Kontakte hochgeladen wurden, wie viele davon angerufen und erreicht wurden, welche Ergebnisse es gab (Termine, Interessiert, Wiedervorlage, kein Interesse), wie viele verworfen oder doppelt waren, wie viele zum Lead wurden – und was aus den Leads wurde (verkauft, reklamiert, aussortiert, offen). Der Balken zeigt den Verlauf Kontakte → angerufen → erreicht → Lead → verkauft. Klickst du an einer Liste auf „Kontakte zeigen“, gilt die Tabelle nur für diese Liste – das steht dann als Marke im Kopf der Tabelle; das Kreuz daran zeigt wieder alle Listen." },
  { id: "gebietskarte", title: "Gebietskarte: Kunden, Einsatzgebiete, Überschneidungen", keys: /gebietskarte|gebiete|einsatzgebiet|überschneid|ueberschneid|mehrfach verkaufen|mehrfachverkauf|plz-?liste|plz liste|welche kunden wo|wo.*kunden|karte.*kunden|kunden.*karte|gleiche plz|selbe plz|excel.*erkenn|ki.*gebiet|gebiet.*ki|1 ?mal|2 ?mal|3 ?mal|verkaufs-?stufe|verkaufbar|einmal verkauf|zweimal|dreimal/i, answer: "Menü „Gebietskarte“ (ganz oben unter Analyse, neben dem Dashboard): Deutschlandkarte mit den Einsatzgebieten eurer Kunden als farbige PLZ-Punkte – jede der 8.204 Zustell-PLZ sitzt am Mittelpunkt ihres echten PLZ-Gebiets. Dazu die PLZ-Gebiete (2-stellig, z. B. „60“) als leicht gefärbte Flächen mit Nummer, oben rechts auf der Karte per Schalter „PLZ-Gebiete“ aus- und einblendbar; der Hinweis an einem Punkt nennt PLZ, Ort, PLZ-Gebiet, Bundesland, die Kunden dort und wie oft sich der Lead verkaufen lässt. Aufbau seit Version 369: oben eine Leiste mit Kunden, abgedeckten PLZ (mit Anteil an allen PLZ in Deutschland), Überschneidungen (Balken: gelb 2×, rot 3×, lila mehr als 3×) und „Mehrfach verkaufbar“; darunter die Karte – oben die Kategorie, links „Wie oft verkaufbar?“ (zugleich Legende und Filter, mit Zahl und Balken je Stufe), unten die Kunden zum Hervorheben. Um Überschneidungen liegt ein farbiger Hof, damit die Stellen sofort auffallen. Rechts die Kunden mit Schalter, PLZ-Zahl, Orten und den Knöpfen zum Bearbeiten und Löschen, darunter die Überschneidungen. „PLZ-Liste hochladen“: Kundenname, Kategorie, Farbe und die PLZ – als Datei (CSV, TXT, Excel) oder eingefügt. Bei einer Datei liest die KI die Struktur von selbst: welche Spalte Kunde, PLZ, Ort, Umkreis (km) oder Kategorie ist, ob die Kunden in Zeilen oder als Spaltenköpfe stehen oder ob die ganze Liste einem Kunden gehört (Name aus dem Dateinamen). Es werden immer alle Zeilen der Datei übernommen. Steht eine Kategorie-Spalte drin (z. B. „Sparte“ PV/WP), entsteht je Kategorie ein eigenes Gebiet; „PV + WP“ zählt für beide, „Nicht angegeben“ bleibt ohne Kategorie. Sie zeigt je Kunde einen Entwurf mit Kategorie, Anzahl PLZ und Hinweisen – Namen und Kategorien lassen sich noch ändern, Häkchen weg nimmt einen Kunden raus – und „N Gebiete anlegen“ legt alle auf einmal an. Gibt es den Kunden in der Kategorie schon, kommen die neuen PLZ standardmäßig dazu („ergänzen“, nichts geht verloren) – auf Wunsch „durch die Liste ersetzen“. Ohne KI-Schlüssel auf dem Server entscheiden Regeln nach Kopfzeile und Inhalt; „Als eine Liste übernehmen“ nimmt alle Zeilen für einen einzigen Kunden. Erlaubt sind 5-stellige PLZ, Vorwahl-Bereiche wie „60“ (alle 60xxx), Bereiche wie „60000-60599“, Orte wie „Hamburg“ und Umkreise wie „München 100 km Umkreis“ (oder Ort + km über „Hinzufügen“). Die Vorschau zeigt, wie viele PLZ erkannt wurden. Die Verkaufs-Stufen links auf der Karte: 1× Verkauf (PLZ mit genau einem Kunden – der Punkt trägt die Farbe des Kunden), 2×, 3× und mehr als 3× – jede Stufe zeigt, wie viele PLZ das sind. Klick schaltet eine Stufe an oder aus, Doppelklick zeigt nur diese Stufe, „Alle Stufen“ schaltet alles wieder an. Die gewählten Stufen werden auf der Karte hervorgehoben, die anderen PLZ bleiben blass sichtbar (nichts verschwindet). Die Liste „Überschneidungen“ zeigt je Kunden-Kombination (z. B. „Aurora + Helios + SonnenKraft – 3× · 83 PLZ · Frankfurt, Offenbach …“), wer sich wie viele PLZ teilt; Klick klappt die PLZ mit Ort auf. Der CSV-Export folgt der Auswahl (gelb = 2 Kunden, rot = 3, lila = mehr als 3). Klick auf einen Kunden (unten auf der Karte oder in der Liste rechts) hebt sein Gebiet hervor mit den Stellen, an denen es sich mit anderen überschneidet – nochmal klicken zeigt wieder alle. Jeder Kunde hat in der Liste rechts einen Schalter: ausgeschaltet bleibt er gespeichert, zählt aber nicht auf der Karte und bei den Überschneidungen. Überschneidungen = PLZ, die bei zwei oder mehr Kunden derselben Kategorie liegen (gelb = 2, rot = 3, lila = mehr als 3) – rechts nach Region gebündelt mit Orten, Klick zeigt jede einzelne PLZ, dazu die Kundenpaare mit gemeinsamen PLZ. Genau dort lässt sich ein Lead mehrfach verkaufen. „Überschneidungen als CSV“ exportiert alles für Excel." },
  { id: "lead-log", title: "Lead-Log: was mit einem Kontakt in der E-Mail-Serie passiert", keys: /lead-?log|was passiert mit|wie lange wartet|nächste e-?mail|welche schritte|schritte offen|fehlermeldung|versand fehlgeschlagen|nicht gesendet|fehler.*kampagne|kampagne.*fehler|stufe.*empfänger|empfänger.*stufe/i, answer: "In der Kampagnen-Ansicht (E-Mail-Kampagnen → Kampagnen → Kampagne öffnen) steht bei jedem Empfänger seine Pipeline-Stufe. Klick auf den Namen oder „Lead-Log“ öffnet das Log: Status, wie lange er noch bis zur nächsten E-Mail wartet (z. B. „wartet noch 2 Tage 3 Std.“), der Weg durch den Ablauf (erledigt, aktuell, offen), alle Ereignisse mit Zeit (gesendet, geöffnet, geklickt, Antwort, Verzweigung, beendet) und ganz oben rot die Fehler mit Grund, wenn eine E-Mail nicht rausging. Fehler erscheinen außerdem in der Glocke und als „⚠ N Fehler“ in der Kampagnenliste. Unten im Log siehst du alle Durchläufe desselben Kontakts." },
  { id: "mehrfach-durchlauf", title: "Mehrfach-Durchlauf: wie oft ein Kontakt durch eine Kampagne darf", keys: /mehrfach|durchlauf|durchläufe|nochmal.*kampagne|erneut.*kampagne|wie oft.*kontakt|kontakt.*wie oft|nur einmal|einmal durch|weiterer durchlauf/i, answer: "Standard: jeder Kontakt geht genau einmal durch eine Kampagne – beim erneuten Starten kommen nur neue Kontakte dazu. Im Kampagnen-Editor unter dem Ablauf schaltest du „Mehrfach-Durchlauf“ ein und wählst bis zu 2×, 3×, 5× oder unbegrenzt. Dann nimmt „Weiterer Durchlauf“ in der Kampagnenliste Kontakte erneut auf, deren letzter Durchlauf beendet ist. Nie, solange ein Durchlauf noch läuft, und nie nach einer Antwort, einem Bounce oder einer Abmeldung. Ein Versandfehler zählt nicht als Durchlauf – nach dem Beheben kommt der Kontakt beim nächsten Start wieder rein." },
  { id: "upload-verlauf", title: "Upload-Verlauf: Uploads und Löschungen", keys: /upload-?verlauf|wann gelöscht|gelöscht.*liste|liste.*gelöscht|wer hat gelöscht|löschungen|hochgeladen.*wann|verlauf.*upload/i, answer: "Der Reiter „Upload-Verlauf“ (in den E-Mail-Kampagnen und in der Kaltakquise-Pipeline) zeigt jeden Upload mit Datum, Liste, Anzahl und Person – und jede Löschung: wann, wie viele Kontakte, aus welcher Liste, von wem und warum (von Hand im Reiter Kontakte, ganze Liste gelöscht, Upload zurückgenommen, Karten aus der Pipeline gelöscht). Mit den Knöpfen Alles / Uploads / Löschungen filterst du. „Rückgängig“ bei einem Upload entfernt genau dessen Kontakte – Kunden bleiben." },
  { id: "freigabe-auswahl", title: "Freigabe: nach Liste filtern und mehrere auf einmal", keys: /freigabe.*(liste|auswahl|mehrere|ankreuzen|massen)|mehrere.*freigeben|massen.*(freigabe|operation)|nach liste filtern/i, answer: "Im Fenster „E-Mails freigeben“ oben die Auswahl „Alle Listen“ → eine hochgeladene Liste wählen: Links stehen nur noch deren Kontakte, und die Knöpfe oben („Alle … freigeben“, „wieder prüfen“, „neu schreiben“) gelten dann nur für diese Liste. Mehrere ankreuzen (Kästchen links an jedem Kontakt oder „Alle … auswählen“) → „Freigeben“, „Wieder prüfen“, „KI neu schreiben“ oder „Aus Funnel nehmen“ gilt genau für die ausgewählten." },
  { id: "kontakte-export", title: "Kontakte exportieren: Excel, CSV oder Google Sheets", keys: /export|exportier|excel|\bcsv\b|google ?sheet|tabelle.*herunter|kontakte.*herunter/i, answer: "Im Reiter „Kontakte“ (E-Mail-Kampagnen oder Vertriebspipeline) steht neben der Anzahl der Knopf „Exportieren“: Excel (.xlsx, Telefonnummern bleiben, wie sie sind), CSV oder Google Sheets (Tabelle kopieren, neues Sheet öffnen, in A1 einfügen). Ohne Auswahl kommen alle Kontakte des Filters, mit Auswahl nur die ausgewählten. Alle auswählen: das Kästchen oben links in der Tabelle wählt direkt alle Kontakte des Filters – auch mehr als die gezeigten 200." },
  { id: "kampagnen-papierkorb", title: "E-Mail-Kampagnen: Gelöschtes und Entferntes wiederherstellen (Papierkorb)", keys: /papierkorb|wiederherstell|gelöscht.*(kampagne|liste|kontakt|empfänger)|(kampagne|liste|empfänger).*gelöscht|entfernt.*(zurück|wieder)|nicht mehr in der liste|stand.*(vorher|wieder)|wie (es )?vorher/i, answer: "E-Mail-Kampagnen → Reiter „Verlauf“ → „Papierkorb“: Dort liegt alles der letzten 60 Tage, was bei den E-Mail-Kampagnen gelöscht oder entfernt wurde – Kontakte und Listen, Empfänger („Entfernen“ bei „nicht mehr in der Liste“, Liste aus der Kampagne genommen, einzeln entfernt) und ganze Kampagnen. „Wiederherstellen“ holt es mit Verlauf zurück (gesendet, geöffnet, geantwortet); wer schon E-Mails hatte, macht dort weiter, wo er stand – niemand bekommt eine E-Mail doppelt. Direkt nach dem Entfernen steht in der Meldung auch „Rückgängig“. Der Papierkorb füllt sich ab diesem Update; was vorher mit „Entfernen“ weg war, findet der Doppelt-Schutz über den Pipeline-Verlauf wieder." },
  { id: "heute-gesendet", title: "Wie viele Kampagnen-E-Mails gingen heute raus?", keys: /heute.*(gesendet|raus|versendet|verschickt)|(gesendet|versendet|raus).*heute|tageslimit|wie viele.*(mails|e-mails).*(raus|gesendet)|tatsächlich.*(raus|gesendet)/i, answer: "Jede Kampagnen-Karte zeigt unter „Gesendet“ „heute X“ – so viele E-Mails dieser Kampagne gingen heute wirklich raus, auch an Kontakte, die inzwischen entfernt oder gelöscht wurden. Oben rechts steht „Heute X von Y Kampagnen-Mails gesendet“ für alle Kampagnen zusammen (Tageslimit). Grundlage ist das Versand-Protokoll: Löschen macht die Zahl nie kleiner und gibt kein Tageslimit frei. „X an Entfernte“ unter „Gesendet“ = E-Mails an Kontakte, die nicht mehr in der Kampagne sind." },
  { id: "ki-tempo", title: "Wie schnell schreibt die KI die Entwürfe – und warum dauert es manchmal länger?", keys: /langsam|dauert.*(lange|ewig)|(ki|entw(ü|ue)rfe?|vorlagen?).*(lange|langsam|schneller|tempo)|tempo|wann.*fertig|schreibt noch/i, answer: "Die KI schreibt jede E-Mail einzeln: Sie liest die Webseite der Firma und schreibt dann den Text in der Fassung, die deine Kampagne verschickt (Drittanbieter-Ansatz oder individueller Vorschlag) – etwa 20–40 Sekunden je Kontakt, 4 gleichzeitig, ohne Pausen dazwischen. Auf der Kampagnen-Karte steht „KI schreibt noch X · ca. Y Min.“ – wie viele noch fehlen und wann sie fertig ist; im Hinweis daneben, wenn der KI-Anbieter gerade bremst (dann versucht es die App automatisch weiter). Bei pausierten Kampagnen schreibt sie nichts von selbst vor. Die zweite Fassung gibt es in der Freigabe auf Klick („Auf Klick schreiben lassen“). Ganz ausschalten kannst du das Vorschreiben je Kampagne: in der Freigabe oben mit dem Schalter „KI schreibt vor: an/aus“ oder auf der Kampagnen-Karte unter „⋯“ → „KI-Vorschreiben ausschalten“. Dann schreibt die KI nur noch, wenn du in der Freigabe einen Kontakt anklickst oder „Nächste Entwürfe schreiben“ wählst; die Karte zeigt „KI-Vorschreiben aus“." },
  { id: "freigabe-loeschen", title: "Kontakte direkt in der Freigabe löschen", keys: /(freigabe|entw(ü|ue)rf).*(l(ö|oe)sch|entfern|raus)|(l(ö|oe)sch|entfern).*(freigabe|entw(ü|ue)rf)|passt nicht.*(firma|kontakt|lead)/i, answer: "In der Freigabe (Kampagnen-Karte → „Zur Freigabe“) löschst du einen Kontakt mit dem Mülleimer oben rechts beim gezeigten Entwurf – danach springt die Freigabe zum nächsten Kontakt. Mehrere auf einmal: links die Kästchen ankreuzen (oder „Alle auswählen“) → „Löschen“. Gelöschte Kontakte verschwinden aus allen Listen, Kampagnen und der Vertriebspipeline und liegen im Papierkorb (E-Mail-Kampagnen → Verlauf → Papierkorb) – mit einem Klick wiederherstellbar. Kunden bleiben erhalten und kommen nur aus dieser Kampagne. Willst du den Kontakt behalten und ihm nur diese Kampagne nicht schicken, nimm „Aus Funnel nehmen“." },
  { id: "kategorie-pruefung", title: "KI prüft, ob die Firma zur Lead-Kategorie passt („Passt nicht?“)", keys: /passt nicht|passt doch|kategorie.*(pr(ü|ue)f|passt|check)|(pr(ü|ue)f|check).*kategorie|falsche (firma|branche)|markiert/i, answer: "Beim Schreiben jedes Entwurfs prüft die KI anhand von Webseite und Angaben, ob die Firma wirklich zur Lead-Kategorie der Kampagne passt (z. B. ein Fachbetrieb, der Alarmanlagen oder Solaranlagen selbst montiert – kein Großhändler, Hersteller, Portal oder ganz andere Branche). Passt sie laut KI nicht, ist der Kontakt rot markiert: „Passt nicht?“ in der Liste und ein Hinweis mit Grund im Entwurf. Auf der Kampagnen-Karte steht „X passen nicht?“ – ein Klick zeigt nur diese. Prüfen und mit dem Mülleimer löschen (mehrere: ankreuzen → „Löschen“). „Alle freigeben“ lässt markierte Kontakte aus; passt die Firma doch, klick „Passt doch“ – dann ist die Markierung weg und kommt auch beim Neuschreiben nicht wieder. Entwürfe, die schon vorher geschrieben waren, prüft die KI bei laufenden Kampagnen nach und nach im Hintergrund nach (ohne sie neu zu schreiben; nicht, wenn „KI schreibt vor“ für die Kampagne aus ist); passt so eine Firma nicht und war sie schon freigegeben, geht sie zurück auf „Zu prüfen“, damit nichts an sie rausgeht. Kosten: Schreiben und Prüfen zusammen etwa 3 Cent je E-Mail, die Nachprüfung allein etwa 0,7 Cent." },
  { id: "ansatz-test", title: "Drittanbieter-Ansatz und individuellen Vorschlag gegeneinander testen (A/B-Test)", keys: /a\/?b|gegeneinander|ansatz.*(test|zuordn|vergleich)|(test|vergleich).*ansatz|25 ?\/? ?50|100 auswählen|drittanbieter.*frei|frei.*drittanbieter/i, answer: "In der Freigabe oben bei „Ansatz“ z. B. „Individueller Vorschlag“ wählen, dann neben „Alle auswählen“ auf „25“, „50“ oder „100“ klicken – das wählt die ersten Kontakte, die gerade links stehen – und unten „Ansatz: Drittanbieter“ (oder „Frei“). Gibt es die andere Fassung schon, wird sofort umgestellt, sonst schreibt die KI sie neu (umgestellte Entwürfe bitte wieder freigeben). Der Ansatz gilt dann auch für die Follow-ups dieser Kontakte. Die nächsten 25: einfach wieder „25“ – die umgestellten stehen ja nicht mehr im Filter. Auswerten: auf der Kampagnen-Karte steht bei „Gesendet“, wie viele E-Mails mit welchem Ansatz rausgingen; in der Kampagne zeigt „Ansätze im Vergleich“ je Ansatz, wie viele angeschrieben wurden, geöffnet, geklickt und geantwortet haben (ab etwa 30–50 Kontakten je Ansatz aussagekräftig)." },
  { id: "doppelt-schutz", title: "Doppelt-Schutz: niemand bekommt dieselbe Kampagne zweimal", keys: /doppelt|zweimal|noch ?einmal.*(erst|erste)|nicht doppelt|zweite erst/i, answer: "Kommt jemand wieder in eine Kampagne, die er schon bekommen hat (z. B. nach „Entfernen“ und erneutem Hinzufügen der Liste), geht die Erst-E-Mail nicht noch einmal raus: Sein Verlauf wird wiederhergestellt und er macht dort weiter, wo er war (Wartezeit, Nachfass-Mail). Zwei offene Einträge derselben Adresse laufen nie parallel. Bewusst noch einmal („In E-Mail-Kampagne“ in der Pipeline, „Weiterer Durchlauf“) bekommt er die Serie von vorn. Was der Schutz geändert hat, steht unter „Rückgängig & Papierkorb“ als „Nicht doppelt“ und lässt sich zurücknehmen." },
  { id: "wieder-in-kampagne", title: "Lead (wieder) in eine E-Mail-Kampagne packen", keys: /wieder.*(e-mail-)?kampagne|in (eine )?(e-mail-)?kampagne.*(packen|aufnehmen|stecken)|zurück in.*kampagne|serie noch einmal/i, answer: "Karte in der Vertriebspipeline aufklappen → „In E-Mail-Kampagne“ → Kampagne wählen. Mehrere auf einmal: oben „Auswählen“ → Karten ankreuzen → „In E-Mail-Kampagne …“. Oder auf der Lead-Seite im Reiter „E-Mail-Serien“. Auch wer schon durch war, geantwortet hat oder aus dem Funnel genommen wurde, bekommt die Serie noch einmal von vorn. Wer gerade in der Kampagne läuft, bekommt sie nicht doppelt; Abgemeldete, Unzustellbare und Gesperrte nie." },
  { id: "karten-verteilen", title: "Karten verteilen: Kontakte auf Vertriebler aufteilen", keys: /karten verteilen|verteilen.*vertriebler|vertriebler.*verteilen|aufteilen|zuteilen.*alle|alle.*zuteilen|prozentual.*karten|karten.*prozent/i, answer: "In der Vertriebspipeline (Knopf „Karten verteilen“ oben rechts – in Kaltakquise, Meta Ads und eigenen Pipelines; in der Pipeline „E-Mail-Kampagne“ gibt es ihn nicht) oder in einer E-Mail-Kampagne (gleicher Knopf oben) wählst du: nur Karten ohne Vertriebler oder alle offenen neu verteilen – dann gleichmäßig, prozentual, feste Anzahl oder nur einer. Die Vorschau zeigt, wer wie viele bekommt. Gewonnene und verlorene Karten bleiben außen vor." },
  { id: "antwort-stopp", title: "Bei Antwort anhalten: Antwort beendet die E-Mail-Serie", keys: /antwort-?stopp|bei antwort anhalten|stoppt.*antwort|antwortet.*(stopp|keine|weitere|anhalten)|geantwortet.*(stopp|serie|mail)|keine weitere e-?mail|weitere e-?mails|abwesenheitsnotiz|out of office|automatische antwort/i, answer: "Der Schalter „Bei Antwort anhalten“ steht im Kampagnen-Editor über dem Ablauf und ist bei jeder Kampagne an – auch bei allen, die schon vorher angelegt waren. Sobald ein Kontakt antwortet, geht an ihn keine weitere E-Mail mehr raus – aus dieser und aus jeder anderen laufenden Serie, egal wie der Ablauf gebaut ist (eine „Wenn geantwortet“-Verzweigung brauchst du dafür nicht). Antworten erkennt die Plattform im Posteingang, über den IMAP-Abgleich oder wenn du beim Empfänger auf „Geantwortet“ klickst. Der Empfänger steht dann auf „Gestoppt – hat geantwortet“, im Verlauf steht „Antwort erhalten – Serie gestoppt“. Abwesenheitsnotizen und automatische Antworten zählen nicht als Antwort. Direkt vor jedem Versand prüft der Zeitplaner noch einmal. Schaltest du den Schalter bei einer Kampagne bewusst aus, läuft diese Serie auch nach einer Antwort zu Ende – die Liste zeigt dann „läuft bei Antwort weiter“. Eine neue Serie, die du später bewusst startest, darf einen Kontakt wieder anschreiben, der früher einmal geantwortet hat." },
  { id: "anrufzaehler", title: "Anrufzähler und Stufe „In Bearbeitung“", keys: /anruf-?z(ä|ae)hler|wie oft angerufen|z(ä|ae)hler|anrufversuch|in bearbeitung|wird gerade angerufen|\+ ?anruf|anruf festhalten|nicht erreicht|mailbox/i, answer: "Jede Karte in der Vertriebspipeline zählt die Anrufversuche – auch ganz ohne Dialer: Klick auf den grünen Telefon-Knopf (oder „+ Anruf“), oben die Nummer antippen (öffnet Telefon-App, Handy oder Softphone), nach dem Auflegen Ergebnis wählen (erreicht, nicht erreicht, besetzt, Mailbox, Rückruf vereinbart, falsche Nummer), optional Notiz und „Wieder anrufen in …“ – fertig. Fehlt die Nummer, trägst du sie direkt im Fenster ein. Im Reiter Kontakte hat jede Zeile denselben Telefon-Knopf. Die Karte zeigt „3× zuletzt heute 10:08 · Mailbox“, auf der Lead-Seite stehen alle Versuche, im Reiter Kontakte die Spalte „Anrufe“. Anrufe über den Dialer zählen automatisch. Du musst nichts mehr verschieben: Der erste Versuch ohne Erfolg bringt die Karte von „Neu“ nach „In Bearbeitung“, sobald du jemanden erreichst, wandert sie nach „Kontaktiert“." },
  { id: "vertriebler", title: "Vertriebler anlegen und verwalten", keys: /vertriebler (anlegen|verwalten|hinzuf|neu|pausieren)|neuer vertriebler|taner|francesco|wer bekommt (die )?karten|vertriebler ohne (login|zugang)/i, answer: "Unter Vertriebspipeline → Einstellungen → „Vertriebler“ legst du Vertriebler an: nur mit Namen (ohne eigenen Login – Karten zuteilen und auswerten geht trotzdem) oder mit E-Mail und Passwort (dann kann er sich selbst anmelden). Dort kannst du auch umbenennen und pausieren – ein pausierter Vertriebler bekommt keine neuen Kontakte, behält aber seine. Fehlen noch alle, legt der Knopf „Taner und Francesco anlegen“ die beiden sofort an." },
  { id: "verteilung-upload", title: "Listen-Upload: Kontakte prozentual verteilen", keys: /prozentual|prozent.*verteil|verteil.*prozent|feste anzahl|verteilung.*(upload|liste)|liste.*verteil|70.?30|gleichm(ä|ae)(ß|ss)ig/i, answer: "Beim Hochladen einer Liste (Vertriebspipeline → Listen) wählst du, wie die Kontakte auf die Vertriebler verteilt werden: gleichmäßig, prozentual (z. B. Taner 70 %, Francesco 30 %), nach fester Anzahl (der Rest bleibt ohne Zuteilung), nur an einen oder später. Du siehst sofort, wie viele Kontakte jeder bekommt (≈ 7 von 10), und die Zuteilung erfolgt im Wechsel, nicht blockweise. Deine letzte Wahl bleibt gemerkt." },
  { id: "einstellungen", title: "Einstellungen", keys: /einstellung|konfiguration|branding|logo|domain|zahlung|abonnement|affiliate|rechnung|passwort|dublettenschutz|doppelte kontakte|api-dokumentation|[äa]lteste leads|leere felder/i, answer: "Einstellungen – links das Menü in vier Gruppen, rechts der gewählte Bereich:\n• Mein Zugang: „Profil“ (Profilbild, Darstellung hell/dunkel; Name und E-Mail-Adresse änderst du unter Benutzer → Stammdaten) und „Passwort“.\n• Firma: „Branding“ (Logo, Name, Farbe, Fußzeile der E-Mails), „Rechnung & Rechtliches“, „Nutzungsbedingungen“.\n• Leads & Auslieferung: „System“ mit fünf Schaltern – älteste Leads zuerst ausliefern, leere Felder nicht mitschicken, kein Käufer bekommt denselben Kontakt zweimal, vorhandene Kontakte beim Hochladen aktualisieren, Ablehnungen automatisch als Reklamation erfassen (PrePing). Gespeichert wird dort erst mit „Änderungen speichern“. Dazu „Reklamationen“ (die Gründe).\n• Versand & Schnittstellen: „E-Mail-Versand“ (Anbieter, Testmail, Absender, Domain-Prüfung), „Integrationen“, „API-Dokumentation“.\nDie früheren Punkte Zahlung, Abonnement und Affiliate gibt es nicht mehr – sie hatten keine Funktion." },
  { id: "support", title: "Support", keys: /support|hilfe|kontakt|whatsapp|problem|fehler|funktioniert nicht/i, answer: "Hilfe: Unter „Support“ erreichst du das Tanesco-Team per WhatsApp oder E-Mail, siehst Anfragen deiner Kunden und den Plattformtest in sechs Schritten. Für einen Fehler bitte Seite, Klick und den Text aus dem Lead-Log oder Protokoll mitschicken." },
];

const normalize = (text: string) => text.toLowerCase().replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss");

/** Beste Antwort aus der Wissensbasis – mehrere Treffer werden kurz kombiniert. */
export function helpAnswer(question: string, context?: { page?: string | null; failedEvents?: number }): string {
  const q = question.trim();
  const scored = HELP_TOPICS.map((topic) => { const matches = q.match(new RegExp(topic.keys.source, "gi")) ?? []; return { topic, score: matches.length }; }).filter((entry) => entry.score > 0).sort((a, b) => b.score - a.score);
  if (!scored.length && context?.page) { const pageTopic = HELP_TOPICS.find((topic) => topic.keys.test(context.page ?? "")); if (pageTopic) scored.push({ topic: pageTopic, score: 1 }); }
  const picked = scored.slice(0, 2).map((entry) => entry.topic);
  const parts: string[] = [];
  if (!picked.length) {
    const pageTopic = context?.page ? HELP_TOPICS.find((topic) => topic.keys.test(context.page ?? "")) : undefined;
    if (pageTopic) parts.push(`Du bist gerade im Bereich „${context?.page}“ – ${pageTopic.answer}`);
    else parts.push(`Dazu habe ich keinen passenden Eintrag. Die Plattform gliedert sich in Dashboard, Leads, Lead-Kategorien, Auslieferung (Bestellungen und ihre Lieferketten), Lieferkette, Automatisierung, Tags, Reklamationen, Callcenter, Vertriebspipeline (Meta Ads), Benutzer, E-Mails, Support und Einstellungen. Frag zum Beispiel: „Wie funktioniert die Lieferkette?“ oder „Was bedeutet Status hängend?“.`);
  } else for (const topic of picked) parts.push(topic.answer);
  if (context?.failedEvents) parts.push(`Hinweis: Aktuell gibt es ${context.failedEvents} fehlgeschlagene Integrationsereignisse – Details unter „API-Fehler“.`);
  return parts.join("\n\n");
}
export const normalizeQuestion = normalize;
